\label{thm:full-couette-final}
There exist absolute constants $c_*>0$ and $C>0$ such that the
following holds. Let $0<\nu\leq1$ and let $u_{\rm in}\in H^2(\Omega)$
be divergence free. If
\begin{equation}
 \varepsilon:=\|u_{\rm in}\|_{H^2(\Omega)}
 +\|u^\perp_{0,\rm in}\|_{\dot B^{-2}_{2,\infty}(\mathbb R^2)}
 \leq c_*\nu,
 \label{eq:main-smallness-final}
\end{equation}
then \eqref{eq:pert} has a unique global solution
\[
 u\in C([0,\infty);H^2(\Omega))
 \cap L^2_{\rm loc}([0,\infty);H^3(\Omega)),
\]
which satisfies
\begin{equation}
 \sup_{t\geq0}\|u(t)\|_{H^2(\Omega)} \leq Cc_*.
 \label{eq:true-Couette-stability-final}
\end{equation}
Moreover, for every $\tau_{0}>0$,
\begin{equation}
 u\in C([\tau_{0},\infty);H^4(\Omega))
 \cap L^2_{\rm loc}([\tau_{0},\infty);H^5(\Omega)).
 \label{eq:full-positive-time-H4}
\end{equation}

\label{thm:global-decay-final}
Under the assumptions of \Cref{thm:full-couette-final}, there exist
absolute constants $\lambda_*>0$ and $C>0$ such that the following
bounds hold.
\begin{enumerate}
\item The nonzero streamwise modes satisfy enhanced dissipation:
\begin{equation}
 \|u_{\neq}(t)\|_{L^2(\Omega)}
 \leq C\varepsilon\mathrm e^{-\lambda_*\nu^{1/3}t},\qquad t\geq0,
 \label{eq:full-ED-final}
\end{equation}
and
\begin{align}
 \nu^{1/6}\|\mathrm e^{\lambda_*\nu^{1/3}t}u_{\neq}\|_{L^2(0,\infty;L^2)}
 +\nu^{1/2}
 \|\mathrm e^{\lambda_*\nu^{1/3}t}\nabla u_{\neq}\|_{L^2(0,\infty;L^2)}
 \leq C\varepsilon.
 \label{eq:global-ED-spacetime}
\end{align}
\item The wall-normal nonzero mode satisfies the inviscid-damping
estimate
\begin{align}
 \|\mathrm e^{\lambda_*\nu^{1/3}t}u^2_{\neq}\|_{L^2(0,\infty;H^1)}
 +\|\mathrm e^{\lambda_*\nu^{1/3}t}
 \partial_x\nabla u^2_{\neq}\|_{L^2(0,\infty;L^2)}
 \leq C\varepsilon.
 \label{eq:global-inviscid-damping}
\end{align}
\item The roll has algebraic decay and retains its endpoint control:
\begin{equation}
 \|u^\perp_{0}(t)\|_{L^2(\mathbb R^2)}
 \leq\frac{C\varepsilon}{1+\nu t},\qquad t\geq0,
 \label{eq:global-roll-decay}
\end{equation}
\begin{equation}
 \sup_{t\geq0}\|u^\perp_{0}(t)\|_{\dot B^{-2}_{2,\infty}}
 +\nu^{1/2}\|u^\perp_{0}\|_{L^2(0,\infty;L^2)}
 \leq C\varepsilon.
 \label{eq:global-roll-endpoint}
\end{equation}
The streak satisfies, after positive-time smoothing,
\begin{align}
 \sup_{t\geq1}\|u^1_{0}(t)\|_{H^4}
 +\nu^{1/2}\|\nabla_{\!\perp}\Delta_{\!\perp}^2u^1_{0}\|_{L^2(1,\infty;L^2)}
 +\nu^{-1}\sup_{t\geq1}\|\partial_tu^1_{0}(t)\|_{H^2}
 \leq C\frac{\varepsilon}{\nu}.
 \label{eq:full-zero-final}
\end{align}
\end{enumerate}

\label{cor:homogeneous-Hminus2}
There exists an absolute constant $c_H>0$ such that, for
$0<\nu\leq1$ and divergence-free $u_{\rm in}\in H^2(\Omega)$,
\begin{equation}
 \varepsilon_H:=\|u_{\rm in}\|_{H^2(\Omega)}
 +\|u^\perp_{0,\rm in}\|_{\dot H^{-2}(\mathbb R^2)}\leq c_H\nu
 \label{eq:Hminus2-smallness}
\end{equation}
implies all conclusions of
\Cref{thm:full-couette-final,thm:global-decay-final}, with
$\varepsilon$ replaced by $\varepsilon_H$ and an adjusted absolute
constant $C$.

\label{cor:weighted-initial-data}
There exists an absolute constant $c_m>0$ such that, for
$0<\nu\leq1$ and divergence-free $u_{\rm in}\in H^2(\Omega)$,
\begin{equation}
 \varepsilon_m:=\|u_{\rm in}\|_{H^2(\Omega)}
 +\||x_\perp|u^\perp_{0,\rm in}\|_{L^1(\mathbb R^2)}\leq c_m\nu
 \label{eq:moment-smallness-global}
\end{equation}
implies all conclusions of
\Cref{thm:full-couette-final,thm:global-decay-final}, with
$\varepsilon$ replaced by $\varepsilon_m$ and an adjusted absolute
constant $C$. In particular, for each fixed $\sigma>2$, it suffices that
\begin{equation}
 \varepsilon_\sigma:=\|u_{\rm in}\|_{H^2(\Omega)}
 +\|\langle x_\perp\rangle^\sigma
 u^\perp_{0,\rm in}\|_{L^2(\mathbb R^2)}\leq c_\sigma\nu.
 \label{eq:weighted-L2-smallness}
\end{equation}
In this case the bounds hold with $\varepsilon_\sigma$ in place of
$\varepsilon$, and the constants may depend on $\sigma$.

\label{lem:H2-restart-initialization-final}
		Let $u_{\rm in}\in H^2(\Omega)$ be divergence free and $u^\perp_{0,\rm in}\in\dot B^{-2}_{2,\infty}(\mathbb R^2)$. Assume $\varepsilon\leq c_{\rm r}\nu$, where $c_{\rm r}>0$ is sufficiently small for the short-time theory (Subsection \ref{app:restart-proof}). Let $u$ be the short-time solution of \Cref{prop:H2-short-time-final}. Then
		\begin{equation}
			\sup_{0\le t\le2}\|u(t)\|_{H^2}^2
			+\nu\int_{0}^2\|u(t)\|_{H^3}^2\,dt\le C\varepsilon^2,
			\qquad
			\sup_{1\le t\le2}\|u(t)\|_{H^4}\le C \frac\varepsilon \nu,
			\label{eq:H2-restart-smoothing-global}
		\end{equation}
		and
		\begin{equation}
			\sup_{0\le t\le1}\|u^\perp_{0}(t)\|_{\dot B^{-2}_{2,\infty}}\le C\varepsilon.
			\label{eq:H2-restart-besov-global}
		\end{equation}
		At physical time $t=1$,
		\begin{equation}
			\|u(1)\|_{H^2}+\|u^\perp_{0}(1)\|_{\dot B^{-2}_{2,\infty}}\le C_{\rm r}\varepsilon,
			\qquad
			\|u(1)\|_{H^4}\le C_{\rm r}\frac{\varepsilon}{\nu},
			\label{eq:H2-restart-sizes-final}
		\end{equation}
		and
		\begin{equation}
			\nu^{-1}\|\partial_t u^1_{0}(1)\|_{H^2}\le C_{\rm r}\frac{\varepsilon}{\nu}.
			\label{eq:H2-restart-at-final}
		\end{equation}
		If all long-time correctors are restarted with zero initial data at physical time one and elapsed time is relabelled as $t=0$, then the standing bounds \eqref{eq:restarted-low-data-standing}--\eqref{eq:restarted-high-data-standing} hold. Moreover,
		\begin{equation}
			E_{2}(0)+E_{4}(0)+E_{6}(0)\le C_{\rm r}\varepsilon,
			\qquad
			E_{1}(0)+E_{3}(0)+E_{5}(0)\le C_{\rm r}\frac{\varepsilon}{\nu}.
			\label{eq:H2-energy-initialization-final}
		\end{equation}

\label{lem:restart-physical-time-final}
		Let $t\geq1$ denote physical time, so that the elapsed time after the restart is $t-1$. Then, for every $\lambda>0$,
		\begin{equation*}
			e^{-\lambda\nu^{1/3}(t-1)}\leq e^\lambda e^{-\lambda\nu^{1/3}t},
		\end{equation*}
		and
		\begin{equation}
			\mu_\nu(t)\leq2\mu_\nu(t-1).
			\label{eq:restart-mu-comparison}
		\end{equation}
		Consequently, every restarted unweighted $Y^m$ estimate on elapsed times $t-1\geq0$ is identical to the corresponding estimate on physical time $t\geq1$, while a factor $\mu_\nu^{1/2}$ loses at most the absolute factor $\sqrt2$ under this conversion.

\label{prop:E6-nonlinear-final}
		Assume $E_{1}(T)+\varepsilon/\nu\leq\delta_*$, with $\delta_*>0$ sufficiently small, and the restarted-data bounds \eqref{eq:restarted-low-data-standing}--\eqref{eq:restarted-high-data-standing},
		\begin{equation}
			E_{6}(T)
			\leq C\left(\|(u^2_{\neq},u^3_{\neq})(0)\|_{H^2}+\|\Delta q(0)\|_{L^2}\right)
			+C\frac{E_{2}(T)}{\nu}E_{6}(T)+C\frac{E_{4}(T)^2}{\nu}.
			\label{eq:E6-nonlinear-final}
		\end{equation}

\label{prop:E3-primary-final}
		Assume \eqref{eq:restarted-low-data-standing}--\eqref{eq:restarted-high-data-standing}. There exists $C>0$ such that
		\begin{align}
			E_{4}(T)
			\leq{}&C\left(\|\Delta u^2_{\neq}(0)\|_{L^2}+\|u^3_{\neq}(0)\|_{H^2}\right)+C E_{6}(T)
			+C\bigl(E_{1}(T)+\frac{\varepsilon}{\nu}\bigr)\bigl(E_{4}(T)+E_{6}(T)\bigr)
			\nonumber\\*
			&+C\frac{E_{2}(T)}{\nu}E_{6}(T)
			+C\frac{E_{4}(T)^2}{\nu}.
			\label{eq:E3-primary-final}
		\end{align}

\label{prop:E4-closed-final}
		Assume \eqref{eq:restarted-low-data-standing}--\eqref{eq:restarted-high-data-standing}. There exists $C>0$ such that
		\begin{align}
			E_{5}(T)
			\leq{}&C\|u_{\neq}(0)\|_{H^4}+C\nu^{-1}\bigl(E_{4}(T)+E_{6}(T)\bigr)
			\nonumber\\*
			&+C\left(E_{1}(T)+\frac{\varepsilon}{\nu}+\frac{E_{2}(T)}{\nu}+\frac{E_{4}(T)}{\nu}\right)E_{5}(T)
			\nonumber\\*
			&+C\frac{E_{1}(T)+\frac{\varepsilon}{\nu}}{\nu}\bigl(E_{4}(T)+E_{6}(T)\bigr)
			+C\frac{E_{3}(T)}{\nu}E_{4}(T).
			\label{eq:E4-closed-final}
		\end{align}

\label{prop:ZR-closed-final}
		Assume \eqref{eq:restarted-low-data-standing}--\eqref{eq:restarted-high-data-standing}. There exists $\delta_*>0$ such that, under the bootstrap smallness
		$\varepsilon+E_{2}(T)+E_{4}(T)\leq\delta_*\nu$,
		\begin{equation}
			E_{2}(T)\leq C\left(\|u^\perp_{0}(0)\|_{H^2}+\|u^\perp_{0}(0)\|_{\dot B^{-2}_{2,\infty}}\right)+C\nu^{-1}E_{4}(T)^2.
			\label{eq:ZR-closed-final}
		\end{equation}

\label{prop:ZR4-closed-final}
		Assume \eqref{eq:restarted-low-data-standing}--\eqref{eq:restarted-high-data-standing}. There exists $\delta_*>0$ such that, if $E_{2}(T)\leq\delta_*\nu$, then
		\begin{equation}
			E_{3}(T)
			\leq C\|u^\perp_{0}(0)\|_{H^4}+C\nu^{-1}\Big(E_{4}(T)^2+E_{4}(T)E_{5}(T)\Big).
			\label{eq:ZR4-closed-final}
		\end{equation}

\label{prop:A-closed-final}
		Assume \eqref{eq:restarted-low-data-standing}--\eqref{eq:restarted-high-data-standing}. Suppose also that $E_{1}(T)\leq\delta_*$ and $E_{2}(T)\leq\delta_*\nu$. Then
		\begin{align}
			E_{1}(T)
			\leq C\Big(&\|u^1_{0}(0)\|_{H^4}+\nu^{-1}\|u^2_{0}(0)\|_{\dot B^{-2}_{2,\infty}}+\frac{E_{2}(T)}{\nu}
			+\frac{E_{2}(T)^2}{\nu^2}
			+\frac{E_{4}(T)^2}{\nu^{4/3}}
			+\frac{E_{4}(T)E_{5}(T)}{\nu}\Big)
			\nonumber\\*
			&+C\frac{E_{2}(T)}{\nu}\bigl(E_{1}(T)+\frac{\varepsilon}{\nu}\bigr).
			\label{eq:A-closed-final}
		\end{align}

\label{lem:six-functional-bootstrap-final}
		Let $0<\nu\leq1$, $\varepsilon>0$, and suppose the restarted initialization \eqref{eq:H2-energy-initialization-final} and the hypotheses of \Cref{prop:E6-nonlinear-final,prop:E3-primary-final,prop:E4-closed-final,prop:ZR4-closed-final,prop:ZR-closed-final,prop:A-closed-final} hold on $[0,T]$. Let $C_{\rm boot}$ dominate the constants in these propositions and let $M\geq M_{0}(C_{\rm boot},C_{\rm r})$. Assume
		\begin{equation*}
			E_{2}+E_{4}+E_{6}\leq M\varepsilon,
			\qquad
			E_{1}+E_{3}+E_{5}\leq M\frac{\varepsilon}{\nu}.
		\end{equation*}
		There exists $\delta_{\rm b}=\delta_{\rm b}(M,C_{\rm boot},C_{\rm r})>0$ such that, if $0<\frac{\varepsilon}{\nu}\leq\delta_{\rm b}$, then
		\begin{equation}
			E_{2}+E_{4}+E_{6}\leq\frac M2\varepsilon,
			\qquad
			E_{1}+E_{3}+E_{5}\leq\frac M2\frac{\varepsilon}{\nu}.
			\label{eq:six-functional-bootstrap-improvement}
		\end{equation}

The order of the proof is
		\begin{equation*}
			(E_{6},E_{4})\longrightarrow E_{2}\longrightarrow E_{5}\longrightarrow E_{3}\longrightarrow E_{1}.
		\end{equation*}

All functionals below are evaluated at the same terminal time $T$. The $E_{6}$ estimate gives
		\begin{equation}
			E_{6}\leq C\varepsilon+C M\frac{\varepsilon}{\nu} E_{6}+C M\frac{\varepsilon}{\nu} E_{4},
			\label{eq:six-functional-E6-first}
		\end{equation}
		because $E_{2}/\nu\leq M\frac{\varepsilon}{\nu}$ and $E_{4}^2/\nu\leq M\frac{\varepsilon}{\nu} E_{4}$. After absorbing the middle term, substitute \eqref{eq:six-functional-E6-first} into the $E_{4}$ estimate. Since $E_{1}+\frac{\varepsilon}{\nu}\leq(M+1)\frac{\varepsilon}{\nu}$, every coefficient multiplying $E_{4}$ or $E_{6}$ is $O_M(\frac{\varepsilon}{\nu})$. For $\delta_{\rm b}$ sufficiently small, the resulting two-by-two low-order system can be absorbed and gives
		\begin{equation}
			(E_{4}+E_{6})\leq C_1\varepsilon\leq\frac M8\varepsilon.
			\label{eq:H2-E36-improve-final}
		\end{equation}
		Here and below $M_{0}$ is enlarged so that each fixed constant $C_j$ is at most $M/8$. This first step uses only the bootstrap bounds for the high-order quantities, not any high-order improvement.

		The closed roll estimate now uses the already improved $E_{4}$ and yields
		\begin{equation}
			E_{2}\leq C\varepsilon+C\nu^{-1}E_{4}^2
			\leq C_2\varepsilon+C M\frac{\varepsilon}{\nu}\,E_{4}
			\leq\frac M8\varepsilon.
			\label{eq:H2-ZR-improve-final}
		\end{equation}
		This completes the low-order block before any high-order functional is improved.

		For $E_{5}$, the genuine restarted initial term satisfies $\|u_{\neq}(0)\|_{H^4}=O(\frac{\varepsilon}{\nu})$. The already improved low-order estimate gives $\nu^{-1}(E_{4}+E_{6})=O(\frac{\varepsilon}{\nu})$. The coefficient of $E_{5}$ is
		\begin{equation*}
			E_{1}+\frac{\varepsilon}{\nu}+\frac{E_{2}}{\nu}+\frac{E_{4}}{\nu}=O_M(\frac{\varepsilon}{\nu}),
		\end{equation*}
		while the remaining couplings satisfy
		\begin{equation*}
			\frac{E_{1}+\frac{\varepsilon}{\nu}}{\nu}(E_{4}+E_{6})=O_M(\frac{\varepsilon^{2}}{\nu^{2}}),
			\qquad
			\frac{E_{3}}{\nu}E_{4}=O_M(\frac{\varepsilon^{2}}{\nu^{2}}).
		\end{equation*}
		After absorption,
		\begin{equation}
			E_{5}\leq C_3\frac{\varepsilon}{\nu}+C_M\frac{\varepsilon^{2}}{\nu^{2}}\leq\frac M8\frac{\varepsilon}{\nu}.
			\label{eq:H2-E4-improve-final}
		\end{equation}
		The high-roll estimate is now evaluated using the improved $E_{4}$ and $E_{5}$:
		\begin{align}
			E_{3}
			\leq C\|u^\perp_{0}(0)\|_{H^4}+C\nu^{-1}\bigl(E_{4}^2+E_{4}E_{5}\bigr)
			\leq C_4\frac{\varepsilon}{\nu}+C_M\frac{\varepsilon^{2}}{\nu^{2}}\leq\frac M8\frac{\varepsilon}{\nu}.
			\label{eq:H2-ZR4-improve-final}
		\end{align}
		Finally, the restarted data give
		\begin{equation*}
			\|u^1_{0}(0)\|_{H^4}+\nu^{-1}\|u^2_{0}(0)\|_{\dot B^{-2}_{2,\infty}}=O(\frac{\varepsilon}{\nu}).
		\end{equation*}
		Using the improved $E_{2}$, $E_{4}$, and $E_{5}$ in \Cref{prop:A-closed-final}, together with the still-valid bootstrap bound for $E_{1}$ only in the absorbable last term, gives
		\begin{equation*}
			E_{1}\leq C_5(\frac{\varepsilon}{\nu}+\frac{\varepsilon^{2}}{\nu^{2}})+C_5\frac{\varepsilon}{\nu} E_{1}.
		\end{equation*}
		After one final absorption,
		\begin{equation}
			E_{1}\leq\frac M8\frac{\varepsilon}{\nu}.
			\label{eq:H2-A-improve-final}
		\end{equation}
		Adding \eqref{eq:H2-E36-improve-final} and \eqref{eq:H2-ZR-improve-final}, and separately adding \eqref{eq:H2-E4-improve-final}, \eqref{eq:H2-ZR4-improve-final}, and \eqref{eq:H2-A-improve-final}, proves \eqref{eq:six-functional-bootstrap-improvement}.

Let $c_{\rm loc}$ be the smallness constant in \Cref{prop:H2-short-time-final}. For the moment assume $c_*\leq\min\{c_{\rm loc},c_{\rm r}\}$; its final size will be fixed below. Then \Cref{lem:H2-restart-initialization-final} applies. Translate physical time $t=1$ to the new origin, denote elapsed time by $t$, and use the same notation $u$ for the translated velocity. Restart all auxiliary correctors with zero initial data. Then \eqref{eq:restarted-low-data-standing}--\eqref{eq:restarted-high-data-standing} and \eqref{eq:H2-energy-initialization-final} hold with the absolute constant $C_{\rm r}$.

		The closure propositions are now applied to the restarted solution. Let $C_{\rm boot}$ dominate the constants in \Cref{prop:E6-nonlinear-final,prop:E3-primary-final,prop:E4-closed-final,prop:ZR4-closed-final,prop:ZR-closed-final,prop:A-closed-final}, and let $\delta_{\rm adm}$ be the minimum of all geometric, modal, interaction, and zero-mode smallness thresholds. The non-circular order of choices is
		\begin{equation*}
			\text{linear modal constants}\longrightarrow(\gamma,\lambda_*)\longrightarrow(\delta_{\rm adm},C_{\rm boot})\longrightarrow M\longrightarrow c_*.
		\end{equation*}
		Choose
		\begin{equation*}
			M\geq\max\left\{M_{0}(C_{\rm boot},C_{\rm r}),64C_{\rm boot}(1+C_{\rm boot}),16C_{\rm r}\right\},
		\end{equation*}
		and then choose $c_*>0$ sufficiently small, depending only on the already fixed constants and $M$, so that
		\begin{equation}
			(C_{\rm r}+M+1)c_*\ll\delta_{\rm adm},
			\qquad C_{\rm boot}(M+1)c_*\le\frac1{64},
			\qquad c_*\leq\delta_{\rm b}(M,C_{\rm boot},C_{\rm r}).
			\label{eq:H2-cstar-choice-final}
		\end{equation}
		On the restarted maximal interval, bootstrap
		\begin{equation}
			E_{2}+E_{4}+E_{6}\le M\varepsilon,
			\qquad
			E_{1}+E_{3}+E_{5}\le M\frac{\varepsilon}{\nu}.
			\label{eq:H2-bootstrap-final}
		\end{equation}
		The initialization follows from \eqref{eq:H2-energy-initialization-final}. The admissibility assumptions in all closure propositions follow from $E_{2}/\nu\le M\frac{\varepsilon}{\nu}$ and $E_{1}+\frac{\varepsilon}{\nu}\le(M+1)\frac{\varepsilon}{\nu}$.

		By \Cref{lem:six-functional-bootstrap-final} and \eqref{eq:H2-cstar-choice-final}, both inequalities in \eqref{eq:H2-bootstrap-final} improve by a factor of two. The bounds for $(E_{6},E_{4})$ are closed first, followed by $E_{2}$, $E_{5}$, $E_{3}$, and $E_{1}$.

		By continuity of the terminal-time functionals and the positive-time $H^4$ continuation criterion, the restarted solution exists for all elapsed times. Joined with the short-time $H^2$ solution, this proves global existence in
		\begin{equation*}
			C([0,\infty);H^2)\cap L^2_{\rm loc}([0,\infty);H^3).
		\end{equation*}
		Since the improved inequalities hold on every finite terminal interval, they also prove the quantitative estimate \eqref{eq:full-energy-final}, with a universal constant depending only on the fixed bootstrap constants.

		For every $\tau_{0}>0$, the short-time smoothing result \eqref{eq:H2-positive-time-H4-continuity} gives $H^4$ continuity up to and across physical time one, and the restarted $H^4$ continuation theory then yields the positive-time regularity asserted in \eqref{eq:full-positive-time-H4}.

		Finally, \eqref{eq:physical-recovery-reorganized} and
\eqref{eq:full-energy-final} imply
$\sup_{t\geq1}\|u(t)\|_{H^2}\leq C\varepsilon/\nu$.
The short-time estimate \eqref{eq:H2-restart-smoothing-global}
controls $0\leq t\leq1$, proving
\eqref{eq:true-Couette-stability-final}. Uniqueness follows from the
local $H^2$ theory and continuation. This proves
\Cref{thm:full-couette-final}.

\label{lem:heat-char}
		It holds for every $f\in L^2(\mathbb R^2)\cap\dot B^{-2}_{2,\infty}(\mathbb R^2)$ that
		\begin{equation}
			\|f\|_{\dot B^{-2}_{2,\infty}} \sim \sup_{\tau>0}\tau\|\mathrm e^{\tau\Delta_{\!\perp}}f\|_{L^2}.
			\label{eq:heat-char}
		\end{equation}
		Consequently, for every $\nu>0$,
		\begin{equation}
			\sup_{t>0}\|t\mathrm e^{\nu t\Delta_{\!\perp}}f\|_{L^2} \lesssim \nu^{-1}\|f\|_{\dot B^{-2}_{2,\infty}}.
			\label{eq:heat-liftup}
		\end{equation}

Since the heat semigroup and $\dot\Delta_j$ commute and the heat multiplier is exponentially small on the support of $\varphi(2^{-j}\cdot)$, almost orthogonality gives
		\begin{equation*}
			\|\mathrm e^{\tau\Delta_{\!\perp}}f\|_{L^2}^2\lesssim\sum_{j\in\mathbb Z}\mathrm e^{-c\tau2^{2j}}\|\dot\Delta_jf\|_{L^2}^2\leq \|f\|_{\dot B^{-2}_{2,\infty}}^2\sum_{j\in\mathbb Z}2^{4j}\mathrm e^{-c\tau2^{2j}}.
		\end{equation*}
		Multiplying by $\tau^2$, we obtain
		\begin{equation*}
			\tau^2\|\mathrm e^{\tau\Delta_{\!\perp}}f\|_{L^2}^2\lesssim \|f\|_{\dot B^{-2}_{2,\infty}}^2\sum_{j\in\mathbb Z}(\tau2^{2j})^2\mathrm e^{-c\tau2^{2j}}\lesssim \|f\|_{\dot B^{-2}_{2,\infty}}^2,
		\end{equation*}
		where the last sum is uniformly bounded because successive values of $\tau2^{2j}$ have ratio $4$. Next, fix $j\in\mathbb Z$ and evaluate the heat semigroup at time $2^{-2j}$. On the support of $\varphi(2^{-j}\xi)$ the factor $\mathrm e^{-2^{-2j}|\xi|^2}$ is bounded below by a positive constant depending only on the fixed annulus. Thus, we have
		\begin{equation*}
			\|\dot\Delta_jf\|_{L^2}\lesssim \|\dot\Delta_j\mathrm e^{2^{-2j}\Delta_{\!\perp}}f\|_{L^2}\lesssim \|\mathrm e^{2^{-2j}\Delta_{\!\perp}}f\|_{L^2}
		\end{equation*}
		which implies
		\begin{equation*}
			2^{-2j}\|\dot\Delta_jf\|_{L^2}\lesssim \sup_{\tau>0}\tau\|\mathrm e^{\tau\Delta_{\!\perp}}f\|_{L^2}.
		\end{equation*}
		Hence, taking the supremum over $j$ proves \eqref{eq:heat-char}. Finally, evaluating the supremum in \eqref{eq:heat-char} at $\nu t$ and dividing by $\nu$ yields \eqref{eq:heat-liftup}.

\label{lem:div-B}
		For every matrix field $F\in L^1(\mathbb R^2;\mathbb R^{2\times2})$,
		\begin{equation}
			\|\mathbb P_{\!\perp}\nabla_{\!\perp}\cdot F\|_{\dot B^{-2}_{2,\infty}} \lesssim \|F\|_{L^1}.
			\label{eq:div-B}
		\end{equation}
		The same estimate holds for a vector field $G\in L^1(\mathbb R^2;\mathbb R^2)$ with $\nabla_{\!\perp}\cdot G$ in place of $\mathbb P_{\!\perp}\nabla_{\!\perp}\cdot F$.

The two-dimensional Leray projector is a bounded Fourier multiplier of order zero on each dyadic annulus. Therefore,
		\begin{equation*}
			\|\dot\Delta_j\mathbb P_{\!\perp}\nabla_{\!\perp}\cdot F\|_{L^2}\lesssim 2^j\|\dot\Delta_jF\|_{L^2}.
		\end{equation*}
		The $L^1$--$L^2$ Bernstein inequality in dimension two gives
		\begin{equation*}
			\|\dot\Delta_jF\|_{L^2}\lesssim 2^j\|F\|_{L^1}
		\end{equation*}
		which implies
		\begin{equation*}
			2^{-2j}\|\dot\Delta_j\mathbb P_{\!\perp}\nabla_{\!\perp}\cdot F\|_{L^2}\lesssim \|F\|_{L^1}
		\end{equation*}
