\label{prop:linear-criticality}
		For every $f\in L^2(\mathbb R^2)$ and $\nu>0$,
		\begin{equation*}
			\sup_{t>0}\|t\mathrm e^{\nu t\Delta_{\!\perp}}f\|_{L^2}\simeq \nu^{-1}\|f\|_{\dot B^{-2}_{2,\infty}}.
		\end{equation*}

For finite Besov norm, the assertion follows from \eqref{eq:heat-char}
by setting $\tau=\nu t$. Conversely, for every $f\in L^2$ and $j\in\mathbb Z$,
the heat multiplier is bounded below on the $j$th annulus at time $2^{-2j}$, so
\begin{equation*}
 2^{-2j}\|\dot\Delta_jf\|_{L^2}
 \leq C2^{-2j}\|\mathrm e^{2^{-2j}\Delta_{\!\perp}}f\|_{L^2}
 \leq C\sup_{\tau>0}\tau\|\mathrm e^{\tau\Delta_{\!\perp}}f\|_{L^2}.
\end{equation*}
Taking the supremum over $j$ shows that finiteness of the heat-side
quantity implies finiteness of the Besov norm. This also proves the
assertion when either side is infinite.

Since $\dot H^{-2}=\dot B^{-2}_{2,2}\hookrightarrow\dot B^{-2}_{2,\infty}$, an $\dot H^{-2}$ condition also controls the linear lift-up, but it is stronger than necessary. More importantly, the actual Leray-projected divergence forcing is naturally endpoint-Besov rather than endpoint-Sobolev. Let $\phi\in C_c^\infty(\mathbb R^2)$ have nonzero mean, set
	\begin{equation*}
		F=\begin{pmatrix}\phi&0\\0&0\end{pmatrix},
		\qquad
		g:=\mathbb P_\perp\operatorname{div}_\perp F,
	\end{equation*}
	and observe from \Cref{lem:div-B} that $g\in\dot B^{-2}_{2,\infty}$. On the other hand,
	\begin{equation*}
		\widehat g(\xi)
		=i\xi_1\left(I-\frac{\xi\otimes\xi}{|\xi|^2}\right)e_1\widehat\phi(\xi),
		\qquad
		|\widehat g(\xi)|^2
		=\frac{\xi_1^2\xi_2^2}{|\xi|^2}|\widehat\phi(\xi)|^2.
	\end{equation*}
	Because $\widehat\phi(0)\neq0$, there are $r_{0},c_{0}>0$ such that $|\widehat\phi(\xi)|\geq c_{0}$ for $|\xi|\leq r_{0}$. On any fixed angular sector on which $|\xi_1|,|\xi_2|\geq c|\xi|$, one therefore has
	\begin{equation*}
		\int_{|\xi|\leq r_{0}}|\xi|^{-4}|\widehat g(\xi)|^2\,d\xi
		\geq c\int_{0}^{r_{0}}\frac{dr}{r}=\infty.
	\end{equation*}
	Thus $g\notin\dot H^{-2}$ even though it has exactly the projected divergence structure of the nonlinear roll forcing. This explains why $\dot H^{-2}$ is not the correct nonlinear endpoint.

\label{prop:moment}
		Let $u^\perp_{0}\in L^1(\mathbb R^2;\mathbb R^2)$ be divergence free and suppose $|x_\perp|u^\perp_{0}\in L^1(\mathbb R^2)$. Then
		\begin{equation}
			\int_{\mathbb R^2}u^\perp_{0}(x_\perp)\,dx_\perp=0
			\label{eq:R-mean-zero}
		\end{equation}
		and
		\begin{equation}
			\|u^\perp_{0}\|_{\dot B^{-2}_{2,\infty}}\leq C\||x_\perp|u^\perp_{0}\|_{L^1}.
			\label{eq:moment-B}
		\end{equation}

Since $u^\perp_{0}\in L^1$, $\widehat u^\perp_{0}$ is continuous. The divergence-free condition gives $\xi\cdot\widehat u^\perp_{0}(\xi)=0$. Taking $\xi=(r,0)$ with $r\neq0$ yields $\widehat u^2_{0}(r,0)=0$, and letting $r\to0$ gives $\widehat u^2_{0}(0)=0$. Similarly, taking $\xi=(0,r)$ gives $\widehat u^3_{0}(0)=0$. Hence \eqref{eq:R-mean-zero} holds.

		Using the zero mean and $|\mathrm e^{-i x\cdot\xi}-1|\leq|x||\xi|$,
		\begin{equation*}
			|\widehat u^\perp_{0}(\xi)|=\lvert\int_{\mathbb R^2}(\mathrm e^{-ix_\perp\cdot\xi}-1)u^\perp_{0}(x_\perp)\,dx_\perp\rvert\leq |\xi|\||x_\perp|u^\perp_{0}\|_{L^1}.
		\end{equation*}
		On the support of the $j$th dyadic block, $|\xi|\simeq2^j$ and the annulus has measure $O(2^{2j})$. Hence Plancherel gives
		\begin{equation*}
			\|\dot\Delta_ju^\perp_{0}\|_{L^2}\lesssim 2^{2j}\||x_\perp|u^\perp_{0}\|_{L^1}.
		\end{equation*}
		Multiplying by $2^{-2j}$ and taking the supremum in $j$ proves \eqref{eq:moment-B}.

\label{thm:roll-main}
		Fix $M\geq1$. There exist constants $c_{0}=c_{0}(M)>0$ and $C=C(M)>0$ such that the following holds. Let $0<\nu\leq1$ and let $u^\perp_{0}$ solve the forced roll equation \eqref{eq:forced-roll} on $[0,T]$. Assume
		\begin{equation*}
			\|u^\perp_{0,\rm in}\|_{L^2}+\|u^\perp_{0,\rm in}\|_{\dot B^{-2}_{2,\infty}}\leq\varepsilon,
		\end{equation*}
		\begin{align}
			\int_{0}^T\|\bigl(u^\perp_{\neq}(t)\otimes u^\perp_{\neq}(t)\bigr)_{0}\|_{L^1}\,dt&\leq M\nu^{-1/3}\varepsilon^2,
