			\|(\nabla u^3_{\neq})D_z^Vu^3_{0}\|_{L^2}
			\leq C E_{2}\mathcal U_1.
		\end{equation*}
		Finally, applying the two-level zero--wave estimate with $b=\nabla D_z^Vu^3_{0}$ and $f=u^3_{\neq}$, and using \eqref{eq:roll-coeff-point-E6} and the two derivative norms in \eqref{eq:R1-time-complete},
