			\|bf\|_{H^2}
			&\leq C\|b\|_{H^1}\|(\partial_x,\partial_z)f\|_{H^2}
			+C\|b\|_{H^3}\|(\partial_x,\partial_z)f\|_{L^2},
			\label{eq:streak-physical-tame-H2}\\
			\|bf\|_{H^3}
			&\leq C\|b\|_{H^1}\|(\partial_x,\partial_z)f\|_{H^3}
			+C\|b\|_{H^3}\|(\partial_x,\partial_z)f\|_{H^1}.
			\label{eq:streak-physical-tame-H3}
		\end{align}

The coefficient products identified in Appendix~\ref{app:functional-tools} give, for $m=2,3$,
\begin{align}
 \|bf\|_{H^m}
 \leq{}&C\|b\|_{H^1}
   (\|f\|_{H^m}+\|\partial_zf\|_{H^m})\nonumber\\
 &+C\|b\|_{H^3}
   (\|f\|_{H^{m-2}}+\|\partial_zf\|_{H^{m-2}}).
 \label{eq:continuous-WZ-tame}
\end{align}
Their proof uses the flat anisotropic products verified on
$\mathbb R^2$ in \Cref{lem:anisotropic-products-R2}, followed by
Leibniz expansion and Sobolev interpolation; these steps are unchanged.
Since $f_{0}=0$,
$\|f\|_{H^r}+\|\partial_zf\|_{H^r}
\leq C\|(\partial_x,\partial_z)f\|_{H^r}$.
Substitution proves both estimates.

