			\label{eq:wide-gap-zero-wave-H3}
		\end{equation}

Let $|\alpha|\leq3$ and let $\beta\leq\alpha$ contain $\ell=|\beta|$ derivatives falling on $b$. Since $b$ is independent of $x$, $\beta$ is purely transverse. The flat product estimate proved in \eqref{eq:flat-fixed-z-product}--\eqref{eq:Hilbert-Sobolev-z}, applied to $\partial^\beta b$ and $\partial^{\alpha-\beta}f$, gives
		\begin{equation}
			\|\partial^\beta b\,\partial^{\alpha-\beta}f\|_{L^2}
			\leq C\|b\|_{H^{\ell+1}(\mathbb R^2)}\,\bigl(\|f\|_{H^{3-\ell}}+\|\partial_zf\|_{H^{3-\ell}}\bigr),
			\qquad 0\leq\ell\leq3.
			\label{eq:wide-gap-Leibniz-level}
		\end{equation}
		Here we have harmlessly enlarged the derivative order on $f$ to $3-\ell$. Put $\theta=\ell/3$. Sobolev interpolation yields
		\begin{align}
			\|b\|_{H^{\ell+1}}
			&\leq \|b\|_{H^1}^{1-\theta}\|b\|_{H^4}^{\theta},\notag\\
			\bigl(\|f\|_{H^{3-\ell}}+\|\partial_zf\|_{H^{3-\ell}}\bigr)
			&\leq \bigl(\|f\|_{H^{3}}+\|\partial_zf\|_{H^{3}}\bigr)^{1-\theta}\bigl(\|f\|_{H^{0}}+\|\partial_zf\|_{H^{0}}\bigr)^{\theta}.\notag
		\end{align}
		Thus each term in \eqref{eq:wide-gap-Leibniz-level} is at most
		\begin{equation*}
\begin{aligned}
&
			\bigl(\|b\|_{H^1}\bigl(\|f\|_{H^{3}}+\|\partial_zf\|_{H^{3}}\bigr)\bigr)^{1-\theta}
			\bigl(\|b\|_{H^4}\bigl(\|f\|_{H^{0}}+\|\partial_zf\|_{H^{0}}\bigr)\bigr)^{\theta}
			\\&\leq \|b\|_{H^1}\bigl(\|f\|_{H^{3}}+\|\partial_zf\|_{H^{3}}\bigr)+\|b\|_{H^4}\bigl(\|f\|_{H^{0}}+\|\partial_zf\|_{H^{0}}\bigr),
\end{aligned}
\end{equation*}
		by the weighted arithmetic--geometric mean inequality. Summing the finitely many Leibniz terms proves \eqref{eq:wide-gap-zero-wave-H3}.

\label{prop:forcing-final}
		Assume the restarted-data bounds \eqref{eq:restarted-low-data-standing}--\eqref{eq:restarted-high-data-standing}, \eqref{eq:variable-small-assumption}, and $E_{1}(T)+\frac{\varepsilon}{\nu}\leq\delta_*$, where $\delta_*$ is sufficiently small. Then
		\begin{equation*}
			\mathfrak F(T)
			\leq C\frac{E_{2}(T)}{\nu}E_{6}(T)+C\frac{E_{4}(T)^2}{\nu}.
		\end{equation*}
		Moreover,
		\begin{align}
			&\|\mathrm e^{2\gamma\nu^{1/3}t}(u^\perp_{0}\cdot\nabla_\perp u_{\neq}+u^\perp_{\neq}\cdot\nabla_\perp u^\perp_{0})\|_{Y^2}
			\nonumber\\
			&\qquad\leq C E_{2}(T)E_{5}(T)+C E_{3}(T)E_{4}(T),
			\label{eq:mixed-Y2-final}
		\end{align}
		and \eqref{eq:wave-Y2-final} controls the $\neq\cdot\neq$ interaction in $Y^2$.

The estimate for $\mathfrak F$ is obtained by summing \Cref{lem:0neq-transport-revised,lem:neq0-transport-revised,lem:mixed-pressure-revised,lem:neqneq-forcing-revised}. We now prove the $Y^2$ estimate with a two-level tensor estimate which keeps the low wave factor at physical order zero. This is the point at which the continuous transverse low frequency matters.

		Extend $u^\perp_{0}$ to $\widetilde u^\perp_{0}=(0,u^2_{0},u^3_{0})$. Since $\operatorname{div}_\perp u^\perp_{0}=0$ and $\operatorname{div}u_{\neq}=0$,
		\begin{equation*}
			u^\perp_{0}\cdot\nabla_\perp u_{\neq}+u^\perp_{\neq}\cdot\nabla_\perp u^\perp_{0}
			=\operatorname{div}\bigl(\widetilde u^\perp_{0}\otimes u_{\neq}+u_{\neq}\otimes\widetilde u^\perp_{0}\bigr).
		\end{equation*}
		Therefore
		\begin{align}
			&\|\mathrm e^{2\gamma\nu^{1/3}t}(u^\perp_{0}\cdot\nabla_\perp u_{\neq}+u^\perp_{\neq}\cdot\nabla_\perp u^\perp_{0})\|_{Y^2}
			\nonumber\\
			&\quad\leq C\|\mathrm e^{2\gamma\nu^{1/3}t}(\widetilde u^\perp_{0}\otimes u_{\neq}+u_{\neq}\otimes\widetilde u^\perp_{0})\|_{L_t^\infty H^3}
			\nonumber\\
			&\qquad+C\nu^{1/2}\|\mathrm e^{2\gamma\nu^{1/3}t}(\widetilde u^\perp_{0}\otimes u_{\neq}+u_{\neq}\otimes\widetilde u^\perp_{0})\|_{L_t^2H^4}.
			\label{eq:mixed-Y2-div-reduction}
		\end{align}

		We record the wave norms used in the two tensor estimates. The definition of $E_{5}$ and the $x$-Poincar\'e inequality give
		\begin{equation}
			\|\mathrm e^{2\gamma\nu^{1/3}t}(u_{\neq},\partial_zu_{\neq})\|_{L_t^\infty H^3}
			+\nu^{1/2}\|\mathrm e^{2\gamma\nu^{1/3}t}(u_{\neq},\partial_zu_{\neq})\|_{L_t^2H^4}
			\leq C E_{5}.
			\label{eq:mixed-wave-high-two-level}
		\end{equation}
		For the lower wave level, \Cref{lem:velocity-reconstruction-final} gives
		\begin{equation*}
			\|u_{\neq}\|_{L^2}+\|\partial_zu_{\neq}\|_{L^2}\leq C\Pi_{0},
			\qquad
			\|u_{\neq}\|_{H^1}+\|\partial_zu_{\neq}\|_{H^1}\leq C(\Pi_{0}+\Pi_1).
		\end{equation*}
		Indeed, $\|\partial_zu_{\neq}\|_{L^2}\leq\|\partial_x\partial_zu_{\neq}\|_{L^2}$ by the streamwise gap, and the latter is contained in \eqref{eq:velocity-reconstruction-final} with $s=0$. Hence \eqref{eq:P-profiles-revised} implies
		\begin{align}
			\|\mathrm e^{2\gamma\nu^{1/3}t}(u_{\neq},\partial_zu_{\neq})\|_{L_t^\infty L^2}
			&\leq C E_{4},
			\label{eq:mixed-low-Linf}\\
			\nu^{1/2}\|\mathrm e^{2\gamma\nu^{1/3}t}(u_{\neq},\partial_zu_{\neq})\|_{L_t^2H^1}
			&\leq C E_{4}.
			\label{eq:mixed-low-L2}
		\end{align}
		For completeness, the $\Pi_{0}$ contribution in \eqref{eq:mixed-low-L2} is
		\begin{equation*}
			\nu^{1/2}\|\mathrm e^{2\gamma\nu^{1/3}t}\Pi_{0}\|_{L_t^2}
			\leq \nu^{1/3}\Bigl(\nu^{1/6}\|\mathrm e^{2\gamma\nu^{1/3}t}\Pi_{0}\|_{L_t^2}\Bigr)
			\leq E_{4},
		\end{equation*}
		whereas the $\Pi_1$ contribution is directly bounded by $E_{4}$. Thus no spurious factor $\nu^{1/3}$ is placed in front of the entire lower wave norm.

		For the $L_t^\infty H^3$ tensor norm, apply \Cref{lem:wide-gap-zero-wave-H3} componentwise with $b=u^j_{0}$ and $f=u^k_{\neq}$. The roll bounds give
		\begin{equation*}
			\|u^\perp_{0}\|_{H^1}\leq C E_{2},
			\qquad
			\|u^\perp_{0}\|_{H^4}\leq E_{3}.
		\end{equation*}
		Using \eqref{eq:mixed-wave-high-two-level} and \eqref{eq:mixed-low-Linf},
		\begin{equation}
			\|\mathrm e^{2\gamma\nu^{1/3}t}(\widetilde u^\perp_{0}\otimes u_{\neq}+u_{\neq}\otimes\widetilde u^\perp_{0})\|_{L_t^\infty H^3}
			\leq C E_{2} E_{5}+C E_{3}E_{4}.
			\label{eq:mixed-tensor-H3}
		\end{equation}
		Notice that the top roll derivatives in this estimate are paired only with $\|u_{\neq}\|_{L^2}+\|\partial_zu_{\neq}\|_{L^2}$, which is controlled pointwise by $\Pi_{0}$; no pointwise $H^1$ norm of the full $u^3_{\neq}$ is used.

		For the dissipative tensor norm, apply \Cref{lem:tame-zero-wave-high} with $m=4$. It gives, componentwise,
		\begin{align}
			\|u^j_{0}u^k_{\neq}\|_{H^4}
			\leq C\|u^j_{0}\|_{H^1}
			\bigl(\|u^k_{\neq}\|_{H^4}+\|\partial_zu^k_{\neq}\|_{H^4}\bigr)
			+C\|u^j_{0}\|_{H^4}
			\bigl(\|u^k_{\neq}\|_{H^1}+\|\partial_zu^k_{\neq}\|_{H^1}\bigr).\notag
		\end{align}
		Multiplying by $\nu^{1/2}\mathrm e^{2\gamma\nu^{1/3}t}$, integrating in time, and using \eqref{eq:mixed-wave-high-two-level} and \eqref{eq:mixed-low-L2}, we obtain
		\begin{equation}
			\nu^{1/2}\|\mathrm e^{2\gamma\nu^{1/3}t}(\widetilde u^\perp_{0}\otimes u_{\neq}+u_{\neq}\otimes\widetilde u^\perp_{0})\|_{L_t^2H^4}
			\leq C E_{2} E_{5}+C E_{3}E_{4}.
			\label{eq:mixed-tensor-H4}
		\end{equation}
		Combining \eqref{eq:mixed-Y2-div-reduction}, \eqref{eq:mixed-tensor-H3}, and \eqref{eq:mixed-tensor-H4} proves \eqref{eq:mixed-Y2-final}. This proof uses the high roll norm only against genuinely lower wave profiles and therefore avoids the false implication $E_{4}+E_{6}\Rightarrow \|u_{\neq}\|_{L_t^\infty H^1}$. Finally, \Cref{lem:wave-Y2-final} gives the $\neq\cdot\neq$ contribution.

\label{lem:primary-forcing-2gamma}
		Assume \eqref{eq:variable-small-assumption} and $E_{1}(T)+\frac{\varepsilon}{\nu}\leq\delta_*$, with $\delta_*$ sufficiently small. Then
		\begin{align}
			\mathfrak F_{\rm prim}(T):={}&
			\nu^{-1/2}\|\mathrm e^{2\gamma\nu^{1/3}t}\nabla g^2\|_{L_t^2L_x^2}
			+\nu^{-1/2}\|\mathrm e^{2\gamma\nu^{1/3}t}(\partial_x,\partial_z)g^3\|_{L_t^2L_x^2}
			\nonumber\\
			&\leq C\frac{E_{2}(T)}{\nu}E_{6}(T)+C\frac{E_{4}(T)^2}{\nu}.
			\label{eq:primary-forcing-2gamma}
		\end{align}

Write
		\begin{equation*}
			K_{0}^{\perp}:=\frac{E_{2}(T)}{\nu}E_{6}(T),
			\qquad
			K_{\neq}:=\frac{E_{4}(T)^2}{\nu}.
		\end{equation*}
		We estimate the two components required by the coupled primary system separately.

		\emph{Step 1: the strong derivative of $g^2$.}
		Expanding the combined forcing,
		\begin{equation}
			\nabla g^2=\nabla (g^2+\kappa g^3)-\nabla(\kappa g^3).
			\label{eq:g2-from-G-primary}
		\end{equation}
		By \Cref{prop:forcing-final}, the complete $E_{6}$ forcing estimate gives
		\begin{equation}
			\nu^{-1/2}\|\mathrm e^{2\gamma\nu^{1/3}t}\nabla (g^2+\kappa g^3)\|_{L_t^2L_x^2}
			\leq
			\nu^{-1/2}\|\mathrm e^{3\gamma\nu^{1/3}t}\nabla (g^2+\kappa g^3)\|_{L_t^2L_x^2}
			\leq C(K_{0}^{\perp}+K_{\neq}).
			\label{eq:g2-G-primary}
		\end{equation}
		By the lower-weight multiplier estimate \eqref{eq:kappa-multiplier-gain-primary} and the weak third-component term in \eqref{eq:Fforcing-final},
		\begin{align}
			\nu^{-1/2}\|\mathrm e^{2\gamma\nu^{1/3}t}\nabla(\kappa g^3)\|_{L_t^2L_x^2}
			&\leq C(E_{1}+\frac{\varepsilon}{\nu})\nu^{-1/6}
			\|\mathrm e^{3\gamma\nu^{1/3}t}\nabla g^3\|_{L_t^2L_x^2}
			\nonumber\\
			&\leq C\delta_*(K_{0}^{\perp}+K_{\neq}).
			\label{eq:g2-kappa-primary}
		\end{align}
		Combining \eqref{eq:g2-from-G-primary}--\eqref{eq:g2-kappa-primary} yields
		\begin{equation}
			\nu^{-1/2}\|\mathrm e^{2\gamma\nu^{1/3}t}\nabla g^2\|_{L_t^2L_x^2}
			\leq C(K_{0}^{\perp}+K_{\neq}).
			\label{eq:g2-primary-final-bound}
		\end{equation}

		\emph{Step 2: the streamwise derivative of $g^3$.}
		The definition of $\mathfrak F$ immediately gives
		\begin{equation}
			\nu^{-1/2}\|\mathrm e^{2\gamma\nu^{1/3}t}\partial_xg^3\|_{L_t^2L_x^2}
			\leq
			\nu^{-1/2}\|\mathrm e^{3\gamma\nu^{1/3}t}\partial_xg^3\|_{L_t^2L_x^2}
			\leq C(K_{0}^{\perp}+K_{\neq}).
			\label{eq:g3-x-primary}
		\end{equation}

		\emph{Step 3: a strong $D_z^V$ derivative of the mixed transport terms.}
		For the $0\cdot\neq$ interaction, use \eqref{eq:g03-BR-decomposition} and the fact that $D_z^V$ is a derivation:
		\begin{align}
			D_z^Vg_{0\neq}^3
			={}&(D_z^V\bigl(u^2_{0}+\kappa u^3_{0}\bigr))\partial_yu^3_{\neq}+\bigl(u^2_{0}+\kappa u^3_{0}\bigr)D_z^V\partial_yu^3_{\neq}
			\nonumber\\
			&+(D_z^Vu^3_{0})D_z^Vu^3_{\neq}+u^3_{0}(D_z^V)^2u^3_{\neq}.
			\label{eq:Dz-g03-primary-expansion}
		\end{align}
		We first record the coefficient bound
		\begin{equation}
			\|D_z^V\bigl(u^2_{0}+\kappa u^3_{0}\bigr)\|_{H^1}
			\leq C E_{2}.
			\label{eq:DzBR-primary}
		\end{equation}
		By the product rule,
		\begin{equation*}
			D_z^V\bigl(u^2_{0}+\kappa u^3_{0}\bigr)=D_z^Vu^2_{0}+(D_z^V\kappa)u^3_{0}+\kappa D_z^Vu^3_{0},
		\end{equation*}
		and \Cref{lem:roll-coefficients-E6}, $\|\kappa\|_{H^3}\leq C\delta_*$, and the two-dimensional $H^2\cdot H^1\to H^1$ product estimate prove \eqref{eq:DzBR-primary}. Moreover,
		\begin{equation*}
			\|(D_z^V)^2u^3_{\neq}\|_{L^2}
			\leq C\|\nabla D_z^Vu^3_{\neq}\|_{L^2}
			\leq C\mathcal U_1,
		\end{equation*}
		while \eqref{eq:E6-D-commuted} gives $\|D_z^V\partial_yu^3_{\neq}\|_{L^2}\leq C\mathcal U_1$. Applying \eqref{eq:anis-prod-L2} to the first and third products in \eqref{eq:Dz-g03-primary-expansion} gives
		\begin{align}
			\|(D_z^V\bigl(u^2_{0}+\kappa u^3_{0}\bigr))\partial_yu^3_{\neq}\|_{L^2}
			+\|(D_z^Vu^3_{0})D_z^Vu^3_{\neq}\|_{L^2}
			\leq C E_{2}\bigl(\mathcal U_{0}+\mathcal U_1\bigr).\notag
		\end{align}
		For the second product, $\bigl(u^2_{0}+\kappa u^3_{0}\bigr)\in H^2(\mathbb R^2)\hookrightarrow L^\infty(\mathbb R^2)$ and \eqref{eq:E6-D-commuted} give
		\begin{equation*}
			\|\bigl(u^2_{0}+\kappa u^3_{0}\bigr)D_z^V\partial_yu^3_{\neq}\|_{L^2}
			\leq C\|\bigl(u^2_{0}+\kappa u^3_{0}\bigr)\|_{H^2}\|D_z^V\partial_yu^3_{\neq}\|_{L^2}
			\leq C E_{2}\mathcal U_1.
		\end{equation*}
		For the fourth product we use the separate pointwise roll recovery $\|u^3_{0}\|_{L^\infty}\leq C E_{2}$ from \Cref{lem:roll-coefficients-E6}:
		\begin{equation*}
			\|u^3_{0}(D_z^V)^2u^3_{\neq}\|_{L^2}
			\leq \|u^3_{0}\|_{L^\infty}\|(D_z^V)^2u^3_{\neq}\|_{L^2}
			\leq C E_{2}\mathcal U_1.
		\end{equation*}
		Consequently,
		\begin{equation*}
			\|D_z^Vg_{0\neq}^3\|_{L^2}
			\leq C E_{2}\bigl(\mathcal U_{0}+\mathcal U_1\bigr).
		\end{equation*}
		Consequently,
		\begin{equation}
			\nu^{-1/2}\|\mathrm e^{3\gamma\nu^{1/3}t}D_z^Vg_{0\neq}^3\|_{L_t^2L_x^2}
			\leq C K_{0}^{\perp},
			\label{eq:Dz-g03-primary-time}
		\end{equation}
		because the $\mathcal U_1$ term uses $\nu^{1/2}\|\mathrm e^{3\gamma\nu^{1/3}t}\mathcal U_1\|_{L_t^2}\lesssim E_{6}$, whereas the $\mathcal U_{0}$ term is smaller by \eqref{eq:U-profiles-revised}.

		For the $\neq\cdot0$ interaction, start from \eqref{eq:gneq0-component-complete}:
		\begin{align}
			D_z^Vg_{\neq0}^3
			=(D_z^Vq)\partial_yu^3_{0}+qD_z^V\partial_yu^3_{0}
			+(D_z^Vu^3_{\neq})D_z^Vu^3_{0}+u^3_{\neq}(D_z^V)^2u^3_{0}.
			\notag
		\end{align}
		The first product is estimated by the two-level inequality \eqref{eq:two-level-zero-wave-E6}:
		\begin{align}
			\|(D_z^Vq)\partial_yu^3_{0}\|_{L^2}
			&\leq C\|\partial_yu^3_{0}\|_{H^1}\|D_z^Vq\|_{L^2}
			+C\|\partial_yu^3_{0}\|_{L^2}\|D_z^Vq\|_{H^1}
			\nonumber\\
			&\leq C\mu_\nu^{-1/2}E_{2}\mathcal U_{0}+C E_{2}\mathcal U_1.
			\label{eq:Dz-gneq0-term1-primary}
		\end{align}
		Next,
		\begin{equation*}
			D_z^V\partial_yu^3_{0}=\partial_yD_z^Vu^3_{0}+(\partial_y\kappa)\partial_yu^3_{0}.
		\end{equation*}
		The first part is estimated pointwise by \eqref{eq:anis-prod-L2}:
		\begin{equation}
			\|q\,\partial_yD_z^Vu^3_{0}\|_{L^2}
			\leq C\bigl(\|\nabla_\perp u^\perp_{0}(t)\|_{H^1}+\|\nabla_\perp D_z^V u^\perp_{0}(t)\|_{H^1}\bigr)\mathcal U_{0}.
			\label{eq:Dz-gneq0-term2a-primary}
		\end{equation}
		The coefficient in the second part is treated in spacetime rather than by an unweighted pointwise estimate. This is the componentwise version of the stronger estimate \eqref{eq:kappagrad-roll-time-E6}; we record the short calculation here because it is used directly in the primary forcing norm. Since $H^2(\mathbb R^2)$ acts as a multiplier on $H^1(\mathbb R^2)$ and $H^1\cdot H^2\to H^1$ in two dimensions,
		\begin{align}
			\nu^{1/2}\|(\partial_y\kappa)\partial_yu^3_{0}\|_{L_t^2H^1}
			&\leq C\nu^{1/2}
			\left(\int_{0}^T\|\kappa(t)\|_{H^2}^2\|\partial_yu^3_{0}(t)\|_{H^2}^2\,dt\right)^{1/2}
			\nonumber\\
			&\leq C(E_{1}+\frac{\varepsilon}{\nu})\nu^{1/2}\|m_\nu^{1/2}\partial_yu^3_{0}\|_{L_t^2H^2}
			\nonumber\\
			&\leq C(E_{1}+\frac{\varepsilon}{\nu})\nu^{1/2}\|\mu_\nu^{1/2}\partial_yu^3_{0}\|_{L_t^2H^2}
			\leq C\delta_* E_{2}.
			\notag
		\end{align}
		Therefore, by \eqref{eq:anis-prod-L2} and \eqref{eq:E6-recovery-low},
		\begin{align}
			&\nu^{-1/2}\|\mathrm e^{3\gamma\nu^{1/3}t}q(\partial_y\kappa)\partial_yu^3_{0}\|_{L_t^2L_x^2}
			\nonumber\\
			&\qquad\leq C\nu^{-1/2}\|(\partial_y\kappa)\partial_yu^3_{0}\|_{L_t^2H^1}
			\|\mathrm e^{3\gamma\nu^{1/3}t}\mathcal U_{0}\|_{L_t^\infty}
			\leq C\delta_* K_{0}^{\perp}.
			\label{eq:Dz-gneq0-term2b-primary-time}
		\end{align}
		Furthermore,
		\begin{equation*}
			\|(D_z^V)^2u^3_{0}\|_{H^1}
			\leq C\|\nabla_\perp D_z^Vu^3_{0}\|_{H^1}
			\leq C\bigl(\|\nabla_\perp u^\perp_{0}(t)\|_{H^1}+\|\nabla_\perp D_z^V u^\perp_{0}(t)\|_{H^1}\bigr),
		\end{equation*}
		because $(D_z^V)^2u^3_{0}=\partial_zD_z^Vu^3_{0}-\kappa\partial_yD_z^Vu^3_{0}$ and $\|\kappa\|_{H^2}$ is small. Therefore \eqref{eq:anis-prod-L2}, \eqref{eq:E6-recovery-low}--\eqref{eq:E6-recovery-high}, and \Cref{lem:roll-coefficients-E6} imply
		\begin{align}
			\|(D_z^Vu^3_{\neq})D_z^Vu^3_{0}\|_{L^2}
			&\leq C E_{2}(\mathcal U_{0}+\mathcal U_1),
			\label{eq:Dz-gneq0-term3-primary}\\
			\|u^3_{\neq}(D_z^V)^2u^3_{0}\|_{L^2}
			&\leq C\bigl(\|\nabla_\perp u^\perp_{0}(t)\|_{H^1}+\|\nabla_\perp D_z^V u^\perp_{0}(t)\|_{H^1}\bigr)\mathcal U_{0}.
			\label{eq:Dz-gneq0-term4-primary}
		\end{align}
		Combining the pointwise terms \eqref{eq:Dz-gneq0-term1-primary}, \eqref{eq:Dz-gneq0-term2a-primary}, \eqref{eq:Dz-gneq0-term3-primary}, and \eqref{eq:Dz-gneq0-term4-primary}, while keeping \eqref{eq:Dz-gneq0-term2b-primary-time} separate, gives
		\begin{align}
			\|D_z^Vg_{\neq0}^3-q(\partial_y\kappa)\partial_yu^3_{0}\|_{L^2}
			\leq{}&C E_{2}\mathcal U_1+C\bigl(\|\nabla_\perp u^\perp_{0}(t)\|_{H^1}+\|\nabla_\perp D_z^V u^\perp_{0}(t)\|_{H^1}\bigr)\mathcal U_{0}
			+C\mu_\nu^{-1/2}E_{2}\mathcal U_{0}.
			\notag
		\end{align}
		The three terms on the right are all integrable with the strong prefactor. Indeed,
		\begin{align}
			\nu^{-1/2}E_{2}\|\mathrm e^{3\gamma\nu^{1/3}t}\mathcal U_1\|_{L_t^2}
			&\leq C K_{0}^{\perp},
			\notag\\
			\nu^{-1/2}\|\bigl(\|\nabla_\perp u^\perp_{0}(t)\|_{H^1}+\|\nabla_\perp D_z^V u^\perp_{0}(t)\|_{H^1}\bigr)\|_{L_t^2}
			\|\mathrm e^{3\gamma\nu^{1/3}t}\mathcal U_{0}\|_{L_t^\infty}
			&\leq C K_{0}^{\perp},
			\notag\\
			\nu^{-1/2}E_{2}\|\mu_\nu^{-1/2}\|_{L_t^\infty}
			\|\mathrm e^{3\gamma\nu^{1/3}t}\mathcal U_{0}\|_{L_t^2}
			&\leq C\nu^{-1/2}\nu^{-1/3}\nu^{-1/6}E_{2}E_{6}
			=C K_{0}^{\perp}.
			\notag
		\end{align}
		Together with the separately estimated term \eqref{eq:Dz-gneq0-term2b-primary-time}, this yields
		\begin{equation}
			\nu^{-1/2}\|\mathrm e^{3\gamma\nu^{1/3}t}D_z^Vg_{\neq0}^3\|_{L_t^2L_x^2}
			\leq C K_{0}^{\perp}.
			\label{eq:Dz-gneq0-primary-time}
		\end{equation}

		To recover the physical $z$ derivative of either transport contribution $h\in\{g_{0\neq}^3,g_{\neq0}^3\}$, use
		\begin{equation*}
			\partial_zh=D_z^Vh+\kappa\partial_yh.
		\end{equation*}
		By \eqref{eq:kappa-multiplier-gain-primary} and the weak estimates in \Cref{lem:0neq-transport-revised,lem:neq0-transport-revised},
		\begin{equation*}
			\nu^{-1/2}\|\mathrm e^{2\gamma\nu^{1/3}t}\kappa\partial_yh\|_{L_t^2L_x^2}
			\leq C(E_{1}+\frac{\varepsilon}{\nu})\nu^{-1/6}\|\mathrm e^{3\gamma\nu^{1/3}t}\nabla h\|_{L_t^2L_x^2}
			\leq C\delta_* K_{0}^{\perp}.
		\end{equation*}
