\label{prop:constant-scalar}
		There exist absolute constants $\gamma_{0}>0$ and $C>0$ such that the following holds. Let $w$ solve
		\begin{equation*}
			L_{0}w=\partial_x f_1+f_2+\operatorname{div}f_3,
			\qquad
			w_{0}=(f_1)_{0}=(f_2)_{0}=(f_3)_{0}=0,
		\end{equation*}
		on $[0,T]$. Then, for $0\leq\sigma\leq\gamma_{0}$,
		\begin{align}
			\|w\|_{X_\sigma([0,T])}^2
			\leq C\Big(&\|w(0)\|_{L^2}^2
			+\|\mathrm e^{\sigma\nu^{1/3}t}\nabla f_1\|_{L^2(0,T;L^2)}^2
			\nonumber\\
			&+\nu^{-1/3}\|\mathrm e^{\sigma\nu^{1/3}t}f_2\|_{L^2(0,T;L^2)}^2
			+\nu^{-1}\|\mathrm e^{\sigma\nu^{1/3}t}f_3\|_{L^2(0,T;L^2)}^2\Big).
			\label{eq:constant-scalar-est}
		\end{align}
		The constant is independent of $T$, $\nu$, and the continuous spanwise frequency.

\label{lem:coordinate-equivalence}
		There exists $\delta_*>0$ such that, if
		\begin{equation}
			\|\nabla_{\!\perp} u^1_{0}(t)\|_{L^\infty}+\|\nabla_{\!\perp}^2u^1_{0}(t)\|_{L^\infty}\leq\delta_*
