		\end{equation}
		for a fixed $t$, then $\Psi_t$ is a $C^1$ diffeomorphism. If $w_{0}=0$, then
		\begin{equation*}
			\|(w\circ\Psi_t^{-1})\|_{L^2}\simeq\|w\|_{L^2},
			\qquad
			\|\nabla (w\circ\Psi_t^{-1})\|_{L^2}\simeq\|\nabla w\|_{L^2},
