			&+\nu^{-1}\|\mathrm e^{\sigma\nu^{1/3}t}\nabla g^3\|_{L_t^2L_x^2}^2\Big).
			\label{eq:r-complementary-est}
		\end{align}

\label{lem:f21-regular}
		Under the hypotheses above,
		\begin{align}
			\nu\|\mathrm e^{\sigma\nu^{1/3}t}\nabla f_{2,1}\|_{L_t^2L_x^2}^2
			\leq C\delta_2^2\Big(&\mathcal E_{\perp,\sigma}(T)
			+\nu^{2/3}\|\Delta w^3(0)\|_{L^2}^2
			\nonumber\\
			&+\nu^{-1/3}\|\mathrm e^{\sigma\nu^{1/3}t}\nabla g^3\|_{L_t^2L_x^2}^2\Big).
			\label{eq:f21-regular-est}
		\end{align}

\label{prop:second-good-unknown}
		Assume \eqref{eq:variable-small-assumption} with $\delta_{0}$ replaced by $\delta_2$. Then
		\begin{align}
			\|\Delta q^{(1)}\|_{X_\sigma}^2
			\leq C\Big(&\|\Delta q(0)\|_{L^2}^2
			+\nu^{-1}\|\mathrm e^{\sigma\nu^{1/3}t}\nabla (g^2+\kappa g^3)\|_{L_t^2L_x^2}^2
			\nonumber\\
			&+\nu^{-1/3}\|\mathrm e^{\sigma\nu^{1/3}t}\nabla g^3\|_{L_t^2L_x^2}^2
			+\delta_2^2\nu^{2/3}\|\Delta w^3(0)\|_{L^2}^2
			\nonumber\\
			&+\delta_2^2\mathcal E_{\perp,\sigma}(T)\Big).
			\label{eq:second-good-unknown-est}
		\end{align}

\label{cor:w1-recovery}
		Assume the hypotheses of \Cref{prop:complementary-transverse-closure} and let $w=(w^1,w^2,w^3)$ be divergence free. Then
		\begin{equation*}
			\|w^1\|_{X_\sigma}^2+\|\partial_x w^1\|_{X_\sigma}^2
			\leq C\mathcal E_{\perp,\sigma}(T).
		\end{equation*}
		Consequently, the right-hand side of \eqref{eq:complementary-transverse-final} controls all three components of the $x$-nonzero velocity in the anisotropic norms required in the nonlinear estimates of Section~\ref{sec:interactions-final}.

\label{lem:average-products}
		Let $N\geq2$. Then
		\begin{align}
			\|(fg)_{0}\|_{L^1(\mathbb R^2)}&\leq \|f\|_{L^2(\Omega)}\|g\|_{L^2(\Omega)},
			\label{eq:avg-L1}\\
			\|(fg)_{0}\|_{L^2(\mathbb R^2)}&\leq C\|f\|_{H^1(\Omega)}\|g\|_{H^1(\Omega)},
			\label{eq:avg-L2}\\
			\|(fg)_{0}\|_{H^N(\mathbb R^2)}&\leq C_N\|f\|_{H^N(\Omega)}\|g\|_{H^N(\Omega)},
			\label{eq:avg-HN}
		\end{align}
		whenever the right-hand sides are finite.

\label{lem:2d-asymmetric-tame}
		For sufficiently regular scalar or vector-valued functions $f,g$ on $\mathbb R^2$,
		\begin{align}
			\|fg\|_{H^2(\mathbb R^2)}
			&\leq C\Big(
			\|f\|_{H^1(\mathbb R^2)}\|g\|_{H^3(\mathbb R^2)}
			+\|f\|_{H^2(\mathbb R^2)}\|g\|_{H^2(\mathbb R^2)}
			\Big),
			\notag\\
			\|fg\|_{H^3(\mathbb R^2)}
			&\leq C\Big(
			\|f\|_{H^2(\mathbb R^2)}\|g\|_{H^3(\mathbb R^2)}
			+\|f\|_{H^3(\mathbb R^2)}\|g\|_{H^2(\mathbb R^2)}
			\Big).
			\notag
		\end{align}
		The estimates hold componentwise for products of vector fields and scalar functions.

\label{lem:anisotropic-products-R2}
		Assume \eqref{eq:variable-small-assumption}, with $\delta_{0}$ sufficiently small. Fix $t\in[0,T]$, set $V=y+u^1_{0}(t,y,z)$, $\kappa=V_z/V_y$, and $D_z^V=\partial_z-\kappa\partial_y$. Let $b=b(y,z)$ and let $f=f(x,y,z)$ satisfy $f_{0}=0$. Then
		\begin{align}
			\|bf\|_{L^2(\Omega)}
			&\leq C\|b\|_{H^1(\mathbb R^2)}
			\left(\|f\|_{L^2(\Omega)}+\|D_z^Vf\|_{L^2(\Omega)}\right),
			\label{eq:anis-prod-L2}
			\\
			\|bf\|_{L^2(\Omega)}
			&\leq C\|b\|_{L^2(\mathbb R^2)}
			\left(\|f\|_{H^1(\Omega)}+\|D_z^Vf\|_{H^1(\Omega)}\right),
			\label{eq:anis-prod-L2-coeff}
			\\
			\|\nabla\Delta^{-1}(bf)\|_{L^2(\Omega)}
			&\leq C\|b\|_{L^2(\mathbb R^2)}
			\left(\|f\|_{L^2(\Omega)}+\|D_z^Vf\|_{L^2(\Omega)}\right),
			\label{eq:anis-prod-Hminus1}
			\\
			\|\nabla(bf)\|_{L^2(\Omega)}
			&\leq C\|b\|_{H^1(\mathbb R^2)}
			\left(\|f\|_{H^1(\Omega)}+\|D_z^Vf\|_{H^1(\Omega)}\right).
			\label{eq:anis-prod-H1}
		\end{align}
		Moreover, for $j\in\{y,z\}$,
		\begin{equation}
			\|[\partial_j\Delta^{-1},b]\Delta f\|_{H^1(\Omega)}
			\leq C\|b\|_{H^2(\mathbb R^2)}
			\left(\|\nabla f\|_{L^2(\Omega)}+\|D_z^V\nabla f\|_{L^2(\Omega)}\right).
			\label{eq:anis-commutator}
		\end{equation}
		The same bounds hold componentwise for vector- and tensor-valued functions. The constant is independent of $t$, $T$, and $\nu$; it depends only on the fixed admissibility threshold in \eqref{eq:variable-small-assumption}. In particular, no norm of $u^1_{0}$ above the $H^4$ level occurring in \eqref{eq:variable-small-assumption} is used.

When $V=y$, one-dimensional Sobolev embedding in $y$ gives
\begin{equation}
 \|b(\cdot,z)f(\cdot,\cdot,z)\|_{L^2_{x,y}}
 \leq C\|b(\cdot,z)\|_{H^1_y}
          \|f(\cdot,\cdot,z)\|_{L^2_{x,y}}.
 \label{eq:flat-fixed-z-product}
\end{equation}
The Hilbert-valued Sobolev inequality on the real $z$ line is
\begin{equation}
 \sup_z\|f(\cdot,\cdot,z)\|_{L^2_{x,y}}
 \leq C(\|f\|_{L^2}+\|\partial_zf\|_{L^2}).
 \label{eq:Hilbert-Sobolev-z}
\end{equation}
These prove \eqref{eq:anis-prod-L2}. Applying the same embedding
successively in $y,z$ yields
\begin{equation}
 \|bf\|_{L^2}\leq\|b\|_{L^2}\sup_{y,z}\|f(\cdot,y,z)\|_{L_x^2}
 \leq C\|b\|_{L^2}(\|f\|_{H^1}+\|\partial_zf\|_{H^1}),
 \label{eq:iterated-Hilbert-Sobolev}
\end{equation}
which proves \eqref{eq:anis-prod-L2-coeff}.
The product rule then gives \eqref{eq:anis-prod-H1}.
These flat product estimates do not require $f_{0}=0$.

For general $V$, the Jacobian is $V_y$, bounded above and away
from zero, and
\begin{equation*}
 \partial_Z(f\circ\Psi_t^{-1})=(D_z^Vf)\circ\Psi_t^{-1}.
\end{equation*}
The $L^2$ and $H^1$ coordinate equivalences in
\Cref{lem:coordinate-equivalence}, and the $H^2$ equivalence for
$b$ following from the chain rule, transfer the three product
estimates to the variable coordinates.

For the negative-order bound, use duality. For every streamwise mean-zero test function $\phi$,
the flat product estimate applied to the $x$-Fourier coefficients,
and then Cauchy--Schwarz in $k$, give
\begin{equation*}
 \|(f\phi)_{0}\|_{L^2(\mathbb R^2)}
 \leq C(\|f\|_{L^2}+\|D_z^Vf\|_{L^2})\|\nabla\phi\|_{L^2}.
\end{equation*}
For general $V$ this follows after the same coordinate change;
the Jacobian is bounded and the $H^1$ norm of each nonzero
$x$-coefficient of $\phi$ is controlled by its full gradient.
Thus
$|\langle bf,\phi\rangle|
\leq C\|b\|_{L^2}(\|f\|_{L^2}+\|D_z^Vf\|_{L^2})\|\nabla\phi\|_{L^2}$,
which proves \eqref{eq:anis-prod-Hminus1}.

Finally, the commutator identity identified above is
\begin{align*}
 [\partial_j\Delta^{-1},b]\Delta f
 =\operatorname{div}\Delta^{-1}((\partial_jb)\nabla f)
 -\partial_j\Delta^{-1}(\nabla_{\!\perp} b\cdot\nabla_{\!\perp} f)
 -\operatorname{div}\Delta^{-1}((\nabla b)\partial_jf).
\end{align*}
Every product on the right is streamwise mean-zero.
The order-minus-one multipliers map $L^2$ to $H^1$ on this
subspace by $|k|\geq1$. Applying \eqref{eq:anis-prod-L2} with
coefficients $\partial_jb$ and $\nabla_{\!\perp} b$ proves
\eqref{eq:anis-commutator}. This completes the domain adaptation.

\label{lem:streamwise-spanwise-bilinear}
		Let $j\in\{x,z\}$ and let $f,g$ be smooth scalar functions on $\Omega=\mathbb T_x\times\mathbb R_y\times\mathbb R_z$.  The estimates \eqref{eq:bilinear-good-derivative}--\eqref{eq:bilinear-good-product} below hold under the additional assumption $g_{0}=0$, whereas the two-level estimates \eqref{eq:bilinear-two-level}--\eqref{eq:bilinear-two-level-derivative} require no mean-zero condition. One has
		\begin{align}
			\|f\,\partial_jg\|_{L^2}
			&\leq C\bigl(\|f\|_{L^2}+\|\partial_jf\|_{L^2}\bigr)\|\Delta g\|_{L^2},
			\label{eq:bilinear-good-derivative}\\
			\|fg\|_{L^2}+\|\partial_j(fg)\|_{L^2}
			&\leq C\bigl(\|f\|_{L^2}+\|\partial_jf\|_{L^2}\bigr)\|g\|_{H^2},
			\label{eq:bilinear-good-product}\\
			\|fg\|_{L^2}
			&\leq C\Big[\bigl(\|f\|_{H^1}+\|\partial_jf\|_{H^1}\bigr)\|g\|_{L^2}
			+\bigl(\|f\|_{L^2}+\|\partial_jf\|_{L^2}\bigr)\|g\|_{H^1}\Big],
			\label{eq:bilinear-two-level}\\
			\|\partial_j(fg)\|_{L^2}
			&\leq C\Big[\bigl(\|f\|_{H^1}+\|\partial_jf\|_{H^1}\bigr)
			\bigl(\|g\|_{L^2}+\|\partial_jg\|_{L^2}\bigr)
			\nonumber\\
			&\hspace{27mm}+\bigl(\|f\|_{L^2}+\|\partial_jf\|_{L^2}\bigr)
			\bigl(\|g\|_{H^1}+\|\partial_jg\|_{H^1}\bigr)\Big].
			\label{eq:bilinear-two-level-derivative}
		\end{align}

\label{lem:mean-zero-high-product}
		Let $f,g$ be smooth scalar functions on $\Omega$ and assume $f_{0}=0$. For $m\in\{1,2,3\}$,
		\begin{equation}
			\|fg\|_{H^m}
			\leq C_m\Big(
			\|\partial_xf\|_{H^{m+1}}\|g\|_{L^2}
			+\|\partial_xf\|_{L^2}\|g\|_{H^{m+1}}
			\Big).
			\label{eq:mean-zero-high-product}
		\end{equation}

\label{lem:tame-zero-wave-high}
		Let $b=b(y,z)$ and let $f=f(x,y,z)$.  For $m\in\{3,4\}$,
		\begin{align}
			\|bf\|_{H^m(\Omega)}
			\leq C_m\Big[&\|b\|_{H^1(\mathbb R^2)}
			\bigl(\|f\|_{H^m(\Omega)}+\|\partial_zf\|_{H^m(\Omega)}\bigr)
			\nonumber\\
			&+\|b\|_{H^m(\mathbb R^2)}
			\bigl(\|f\|_{H^1(\Omega)}+\|\partial_zf\|_{H^1(\Omega)}\bigr)\Big].
			\label{eq:tame-zero-wave-high}
		\end{align}

The flat versions of \eqref{eq:anis-prod-L2} and \eqref{eq:anis-prod-H1}
hold without a mean-zero assumption, as proved above. In particular,
\begin{equation}
 \|\nabla(bF)\|_{L^2}\leq C\|b\|_{H^1}
       (\|F\|_{H^1}+\|\partial_zF\|_{H^1}).
 \label{eq:tame-base-H1}
\end{equation}
Use $\|G\|_{H^m}\leq C_m(\|G\|_{L^2}+
\sum_{j\in\{x,y,z\}}\|\nabla\partial_j^{m-1}G\|_{L^2})$ and expand by Leibniz's rule.
The zeroth-order term is controlled by the flat $L^2$ product estimate.
Since $\partial_xb=0$, each differentiated term is bounded by
\begin{equation}
 C\|b\|_{H^{\ell+1}}
 (\|f\|_{H^{m-\ell}}+\|\partial_zf\|_{H^{m-\ell}}),
 \qquad 0\leq\ell\leq m-1.
 \label{eq:tame-intermediate-term}
\end{equation}
Interpolation with exponent $\ell/(m-1)$ bounds this product by
\begin{equation*}
 C\bigl[\|b\|_{H^1}(\|f\|_{H^m}+\|\partial_zf\|_{H^m})\bigr]^{1-\ell/(m-1)}
  \bigl[\|b\|_{H^m}(\|f\|_{H^1}+\|\partial_zf\|_{H^1})\bigr]^{\ell/(m-1)}.
\end{equation*}
Young's inequality and summation give \eqref{eq:tame-zero-wave-high}.

\label{lem:mnu-interpolation-revised}
		With the weight $m_\nu$ defined in Section~\ref{sec:full-system}, for $r=2,3$ and every sufficiently regular function $F$,
		\begin{equation}
			m_\nu(t)\|F(t)\|_{H^r}
			\leq C\nu\|F(t)\|_{H^{r+1}}
			+C\nu(1+t)^3\|F(t)\|_{H^{r-2}}.
			\label{eq:mnu-interpolation-revised}
		\end{equation}
		Moreover,
		\begin{equation}
			\sup_{t\geq0}\nu(1+t)^3\mathrm e^{-\gamma\nu^{1/3}t}\leq C_\gamma.
			\label{eq:weight-gap-polynomial-revised}
		\end{equation}

For the shifted and capped transient factor, Sobolev interpolation
and Young's inequality give
\begin{equation*}
 m_\nu\|F\|_{H^r}
 \leq C m_\nu\|F\|_{H^{r+1}}^{2/3}\|F\|_{H^{r-2}}^{1/3}
 \leq C\nu\|F\|_{H^{r+1}}
 +C m_\nu^3\nu^{-2}\|F\|_{H^{r-2}}.
\end{equation*}
Since $m_\nu\leq\nu(1+t)$, the last coefficient is at most
$\nu(1+t)^3$. With $s=\nu^{1/3}t$, the coefficient in
\eqref{eq:weight-gap-polynomial-revised} equals
$(\nu^{1/3}+s)^3\mathrm e^{-\gamma s}$, which is uniformly bounded.

\label{prop:H2-short-time-final}
		There exist absolute constants $c_{\rm loc},C>0$ such that, if $u_{\rm in}\in H^2(\Omega)$ is divergence free and
		\[
		\|u_{\rm in}\|_{H^2}\le c_{\rm loc}\nu,
		\]
		then \eqref{eq:pert} has a unique solution on $[0,2]$ satisfying
		\begin{equation}
			\sup_{0\le t\le2}\|u(t)\|_{H^2}^2+\nu\int_{0}^2\|u(t)\|_{H^3}^2\,dt\le C\|u_{\rm in}\|_{H^2}^2.
			\label{eq:H2-local-energy-final}
		\end{equation}
		For $m=3,4$,
		\begin{equation}
			\sup_{0<t\le2}(\nu t)^{m-2}\|u(t)\|_{H^m}^2
			+\nu\int_{0}^2(\nu t)^{m-2}\|u(t)\|_{H^{m+1}}^2\,dt
			\le C\|u_{\rm in}\|_{H^2}^2.
			\label{eq:H2-weighted-smoothing-final}
		\end{equation}
		In particular,
		\begin{equation}
			\nu\sup_{1\le t\le2}\|u(t)\|_{H^4}\le C\|u_{\rm in}\|_{H^2}.
			\label{eq:H2-to-H4-final}
		\end{equation}
		The streak component also satisfies
		\begin{equation}
			\sup_{1\le t\le2}\|\partial_t u^1_{0}(t)\|_{H^2}\le C\|u_{\rm in}\|_{H^2}.
			\label{eq:H2-at-final}
		\end{equation}
		Consequently $u(1)\in H^4$, so the $H^4$ continuation theory below applies from physical time one onward.

On $0\le t\le2$, pass to Kelvin variables $X=x-ty$ and $U(t,X,y,z)=u(t,X+ty,y,z)$. The equation has uniformly elliptic viscous operator $\Delta_L$ and the standard transport cancellation. Friedrichs regularization gives smooth divergence-free approximate solutions. At the $H^2$ level, the tame product estimate and Young's inequality give
		\begin{equation}
			\frac{d}{dt}\|U\|_{H^2}^2+c\nu\|U\|_{H^3}^2
			\le C\|U\|_{H^2}^2+C\nu^{-1}\|U\|_{H^2}^4.
			\label{eq:H2-energy-proof-final}
		\end{equation}
		Indeed, the nonlinear commutators are bounded by $C\|U\|_{H^2}^2\|U\|_{H^3}$, which is absorbed into the dissipation up to the last term in \eqref{eq:H2-energy-proof-final}. A continuity argument under $\|U(0)\|_{H^2}\le c_{\rm loc}\nu$ yields \eqref{eq:H2-local-energy-final}.

		We next prove the weighted smoothing estimate without using any positive-time Sobolev norm as an initial datum. For $m=3,4$, the differentiated regularized equation and the same transport cancellation give
		\begin{equation}
			\frac{d}{dt}\|U\|_{H^m}^2+c\nu\|U\|_{H^{m+1}}^2
			\leq C_m\left(1+\nu^{-1}\|U(t)\|_{H^2}^2+\|U(t)\|_{H^3}\right)\|U\|_{H^m}^2,
			\label{eq:H2-smoothing-unweighted-m}
		\end{equation}
		where the nonlinear commutators obey
		\begin{equation*}
			|\mathcal N_m|\le \frac{c\nu}{4}\|U\|_{H^{m+1}}^2+C_m\nu^{-1}\|U\|_{H^2}^2\|U\|_{H^m}^2+C_m\|U\|_{H^3}\|U\|_{H^m}^2,
		\end{equation*}

		The local $H^2$ bound gives
		\begin{equation}
			\int_{0}^2C_m\left(1+\nu^{-1}\|U(t)\|_{H^2}^2+\|U(t)\|_{H^3}\right)\,dt\leq C_m,
			\qquad
			\nu\int_{0}^2\|U(t)\|_{H^3}^2\,dt\leq C\|u_{\rm in}\|_{H^2}^2,
			\label{eq:H2-smoothing-K-integrable}
		\end{equation}
		where we used $\|u_{\rm in}\|_{H^2}\leq c_{\rm loc}\nu$ and Cauchy--Schwarz for the $L_t^1H^3$ term.

		For $m=3$, multiply \eqref{eq:H2-smoothing-unweighted-m} by $\nu t$. Since $\partial_t(\nu t)=\nu$,
		\begin{equation*}
			\frac{d}{dt}\left[(\nu t)\|U\|_{H^3}^2\right]
			+c\nu(\nu t)\|U\|_{H^4}^2
			\leq \nu\|U\|_{H^3}^2+C_3\left(1+\nu^{-1}\|U(t)\|_{H^2}^2+\|U(t)\|_{H^3}\right)(\nu t)\|U\|_{H^3}^2.
		\end{equation*}
		The first term on the right is exactly controlled by the $H^2$ dissipation in \eqref{eq:H2-local-energy-final}. Since the weighted quantity vanishes at $t=0$, Gronwall's inequality and \eqref{eq:H2-smoothing-K-integrable} yield
		\begin{equation}
			\sup_{0<t\leq2}(\nu t)\|U(t)\|_{H^3}^2
			+\nu\int_{0}^2(\nu t)\|U(t)\|_{H^4}^2\,dt
			\leq C\|u_{\rm in}\|_{H^2}^2.
			\label{eq:H2-smoothing-m3-closed}
		\end{equation}

		For $m=4$, multiply \eqref{eq:H2-smoothing-unweighted-m} by $(\nu t)^2$. Since $\partial_t(\nu t)^2=2\nu(\nu t)$,
		\begin{equation}
			\frac{d}{dt}\left[(\nu t)^2\|U\|_{H^4}^2\right]
			+c\nu(\nu t)^2\|U\|_{H^5}^2
			\leq 2\nu(\nu t)\|U\|_{H^4}^2+C_4\left(1+\nu^{-1}\|U(t)\|_{H^2}^2+\|U(t)\|_{H^3}\right)(\nu t)^2\|U\|_{H^4}^2.
			\label{eq:H2-smoothing-m4-weighted}
		\end{equation}
		The first term on the right is controlled by the weighted $H^3$ dissipation in \eqref{eq:H2-smoothing-m3-closed}. A second application of Gronwall therefore gives
		\begin{equation}
			\sup_{0<t\leq2}(\nu t)^2\|U(t)\|_{H^4}^2
			+\nu\int_{0}^2(\nu t)^2\|U(t)\|_{H^5}^2\,dt
			\leq C\|u_{\rm in}\|_{H^2}^2.
			\label{eq:H2-smoothing-m4-closed}
		\end{equation}
		Equations \eqref{eq:H2-smoothing-m3-closed}--\eqref{eq:H2-smoothing-m4-closed} prove \eqref{eq:H2-weighted-smoothing-final}. In particular, \eqref{eq:H2-to-H4-final} follows by restricting \eqref{eq:H2-smoothing-m4-closed} to $1\leq t\leq2$. Moreover, for every $\tau>0$ the same estimates give $U\in L^\infty(\tau,2;H^4)\cap L^2(\tau,2;H^5)$, while the equation gives $\partial_tU\in L^2(\tau,2;H^3)$. The Hilbert-triple continuity theorem therefore yields
		\begin{equation}
			U\in C([\tau,2];H^4),\qquad \tau>0.
			\label{eq:H2-positive-time-H4-continuity}
		\end{equation}
		Thus the value $u(1)\in H^4$ is well defined in the strong topology.

		Finally, the zero-mode streak equation is
		\[
		\partial_t u^1_{0}=\nu\Delta_\perp u^1_{0}-u^2_{0}-\nabla_\perp\cdot(u^\perp_{0}u^1_{0}+(u^\perp_{\neq}u^1_{\neq})_{0}).
		\]
		For $1\le t\le2$, the preceding $H^2$ and $H^4$ estimates and the two-dimensional tame products yield
		\[
		\|\partial_t u^1_{0}\|_{H^2}\le \nu\|u^1_{0}\|_{H^4}+\|u^\perp_{0}\|_{H^2}+C\|u\|_{H^2}\|u\|_{H^4}\le C\|u_{\rm in}\|_{H^2},
		\]
		provided $c_{\rm loc}$ is sufficiently small. This proves \eqref{eq:H2-at-final}. Compactness of the Friedrichs approximations gives the asserted solution and uniqueness at the $H^2$ level.

\label{lem:short-besov-final}
		Under the assumptions of \Cref{prop:H2-short-time-final}, assume $u^\perp_{0,\rm in}\in\dot B^{-2}_{2,\infty}(\mathbb R^2)$. Then
		\begin{equation}
			\sup_{0\le t\le1}\|u^\perp_{0}(t)\|_{\dot B^{-2}_{2,\infty}}
			\le \|u^\perp_{0,\rm in}\|_{\dot B^{-2}_{2,\infty}}+C\|u_{\rm in}\|_{H^2}^2.
			\label{eq:short-besov-final}
		\end{equation}

The exact roll equation is
		\[
		\partial_tu^\perp_{0}-
u\Delta_\perp u^\perp_{0}=-P_\perp
abla_\perp\cdot igl(u^\perp_{0}\otimes u^\perp_{0}+(u^\perp_{
eq}\otimes u^\perp_{
eq})_{0} igr).
		\]
		The Duhamel formula, boundedness of the heat semigroup on $\dot B^{-2}_{2,\infty}$, and the projected-divergence endpoint estimate from \Cref{sec:prelim} give
		\[
		\|u^\perp_{0}(t)\|_{\dot B^{-2}_{2,\infty}}\le \|u^\perp_{0,m in}\|_{\dot B^{-2}_{2,\infty}}+C\int_{0}^t igl(\|u^\perp_{0}(s)\|_{L^2}^2+\| igl(u^\perp_{
eq}(s)\otimes u^\perp_{
eq}(s) igr)_{0}\|_{L^1} igr)\,ds.
		\]
		Since $\| igl(u^\perp_{
eq}(s)\otimes u^\perp_{
eq}(s) igr)_{0}\|_{L^1}\le\|u_{
eq}(s)\|_{L^2}^2$, \eqref{eq:H2-local-energy-final} proves \eqref{eq:short-besov-final}.

Proposition~\ref{prop:H2-short-time-final} gives \eqref{eq:H2-restart-smoothing-global}. Lemma~\ref{lem:short-besov-final} gives \eqref{eq:H2-restart-besov-global}, since $\varepsilon\leq c_{\rm r}\nu\leq c_{\rm r}$. They give the first two terms in \eqref{eq:H2-restart-sizes-final}; the $H^4$ bound follows from $\nu\|u(1)\|_{H^4}\leq C\varepsilon$. Equation \eqref{eq:H2-at-final} gives \eqref{eq:H2-restart-at-final}.

		It remains to verify the auxiliary low-order initial quantities. At physical time one, the shear coefficient is $\partial_z u^1_{0}(1)/(1+\partial_y u^1_{0}(1))$.
		For $c_{\rm r}$ sufficiently small, \eqref{eq:H2-restart-sizes-final} gives $\|\nabla_\perp u^1_{0}(1)\|_{L^\infty}\leq1/4$. The two-dimensional Moser estimate therefore yields
		\begin{equation*}
			\|\frac{\partial_zu^1_{0}(1)}{1+\partial_yu^1_{0}(1)}\|_{H^3(\mathbb R^2)}\leq C\|u^1_{0}(1)\|_{H^4}\leq C\frac{\varepsilon}{\nu}.
		\end{equation*}
		The mixed-dimensional Sobolev product estimates then give
		\begin{equation}
\begin{aligned}
&
			\|\Delta \left(u^2_{\neq}(1)+\frac{\partial_z u^1_{0}(1)}{1+\partial_yu^1_{0}(1)}u^3_{\neq}(1)\right)\|_{L^2}
			\\&\quad+\sum_{j=2}^3\left(\|\partial_x^2u^j_{\neq}(1)\|_{L^2}+\|\partial_x\left(\partial_z-\frac{\partial_z u^1_{0}(1)}{1+\partial_y u^1_{0}(1)}\partial_y\right)u^j_{\neq}(1)\|_{L^2}\right)
			\\&\quad+\|\partial_x\nabla \left(u^2_{\neq}(1)+\frac{\partial_z u^1_{0}(1)}{1+\partial_yu^1_{0}(1)}u^3_{\neq}(1)\right)\|_{L^2}
			\\&\leq C\|u_{\neq}(1)\|_{H^2}
			\leq C\varepsilon.
\end{aligned}
\label{eq:H2-restart-good-initial}
\end{equation}
		The restarted singular correctors satisfy $q^{(2)}(0)=q^{(3)}(0)=0$. Thus the complementary scalar starts from $\Delta u^3_{\neq}(1)$, and
		\begin{equation}
			\|\Delta u^3_{\neq}(1)\|_{L^2}\leq C\varepsilon.
			\label{eq:H2-restart-r-initial}
		\end{equation}
		Thus \eqref{eq:restarted-low-data-standing} follows from \eqref{eq:H2-restart-sizes-final}, \eqref{eq:H2-restart-good-initial}, and \eqref{eq:H2-restart-r-initial}, while \eqref{eq:restarted-high-data-standing} follows from \eqref{eq:H2-restart-sizes-final}--\eqref{eq:H2-restart-at-final}.

		Finally, the definitions of $E_{4}$ and $E_{6}$ together with \eqref{eq:H2-restart-good-initial} show that their initial values are $O(\varepsilon)$. The $H^2$ and Besov bounds for $u^\perp_{0}(1)$ control every initial component of $E_{2}$, because $\mu_\nu(0)\leq1$. The high-order bounds in \eqref{eq:H2-restart-sizes-final} control $E_{5}(0)$ and $E_{3}(0)$, while \eqref{eq:H2-restart-sizes-final}--\eqref{eq:H2-restart-at-final} control $E_{1}(0)$. The spacetime dissipative pieces vanish at terminal time zero. This proves \eqref{eq:H2-energy-initialization-final}.

\label{def:H4-strong-solution}
		Let $T>0$. A pair $(u,p)$ is an $H^4$ strong solution of \eqref{eq:pert} on $[0,T]$ if, after the Kelvin change of variables
		\begin{equation}
			X=x-ty,
			\qquad
			U(t,X,y,z)=u(t,X+ty,y,z),
			\qquad
			P(t,X,y,z)=p(t,X+ty,y,z),
			\label{eq:strong-solution-Kelvin}
		\end{equation}
		one has
		\begin{equation*}
			U\in C([0,T];H^4(\Omega))\cap L^2(0,T;H^5(\Omega)),
			\qquad
			\partial_tU\in L^2(0,T;H^3(\Omega)),
		\end{equation*}
		\begin{equation*}
			\nabla_LP\in L^2(0,T;H^3(\Omega)),
			\qquad
			\nabla_L\cdot U=0,
		\end{equation*}
		and the Kelvin system \eqref{eq:Kelvin-local-system} holds almost everywhere. The pressure is understood modulo an additive function of time. On every compact time interval the Kelvin and physical Sobolev norms are equivalent, so the definition is unchanged if the Kelvin clock is reset at an arbitrary reference time.

\label{lem:local-continuation-final}
		For every divergence-free $u_{\rm in}\in H^4(\Omega)$ and every $0<\nu\leq1$, equation \eqref{eq:pert} has a unique $H^4$ strong solution on a maximal interval $[0,T_{\max})$. The local lifespan after a restart at time $t_{0}<T_{\max}$ has a positive lower bound depending only on $\nu$ and $\|u(t_{0})\|_{H^4}$, and not on $t_{0}$. In particular,
		\begin{equation}
			T_{\max}<\infty
			\quad\Longrightarrow\quad
			\limsup_{t\uparrow T_{\max}}\|u(t)\|_{H^4}=\infty.
			\label{eq:H4-blowup-alternative}
		\end{equation}
		If $T_{\max}<\infty$ and
		\begin{equation}
			\sup_{0<T<T_{\max}}\bigl(\sum_{j=1}^6 E_{j}(T)\bigr)<\infty,
			\label{eq:continuation-uniform-revised}
		\end{equation}
		then the solution extends beyond $T_{\max}$. Consequently, any a priori argument which keeps these six quantities uniformly bounded forces $T_{\max}=\infty$.

In the Kelvin variables \eqref{eq:strong-solution-Kelvin}, the system is
\begin{equation}
 \partial_tU-\nu\Delta_LU+U^2e_1+U\cdot\nabla_LU+\nabla_LP=0,
 \qquad \nabla_L\cdot U=0,
 \label{eq:Kelvin-local-system}
\end{equation}
with
\begin{equation}
 \Delta_LP=-2\partial_XU^2-\partial_i^LU^j\partial_j^LU^i,
 \qquad \partial^L=(\partial_X,\partial_y-t\partial_X,\partial_z).
 \label{eq:Kelvin-pressure-local}
\end{equation}
On $0\leq t\leq1$, the Kelvin and ordinary Sobolev norms are uniformly
equivalent. The pressure operators $\nabla_L\Delta_L^{-1}\partial_X$
and $\nabla_L\Delta_L^{-1}\operatorname{div}_L$ are bounded order-zero
Fourier multipliers; their symbols at the origin are set to zero.

Let $\mathcal J_N$ be the orthogonal projector onto
$k^2+\eta^2+\ell^2\leq N^2$. On its band-limited Hilbert space, solve
\begin{equation}
 \partial_tU_N-\nu\Delta_LU_N+U_N^2e_1
 +\mathcal J_N(U_N\cdot\nabla_LU_N)+\nabla_LP_N=0,
 \qquad U_N(0)=\mathcal J_Nu_{\rm in},
 \label{eq:Friedrichs-Kelvin}
\end{equation}
where
\begin{equation}
 \Delta_LP_N=-2\partial_XU_N^2
 -\operatorname{div}_L\mathcal J_N(U_N\cdot\nabla_LU_N).
 \label{eq:Friedrichs-pressure}
\end{equation}
The right-hand side is locally Lipschitz in $H^4$ for fixed $N$,
so Picard's theorem applies. Since $\mathcal J_N$ commutes with $\nabla_L$
and $\partial_t(\nabla_L\cdot U_N)=\nabla_L\cdot\partial_tU_N-\partial_XU_N^2$,
the divergence solves the homogeneous heat equation with zero data.
Thus $\nabla_L\cdot U_N=0$ and $\mathcal J_NU_N=U_N$.

The pressure and principal transport terms cancel in the $H^4$ energy.
The Moser commutator estimate gives
\begin{equation*}
 \frac{d}{dt}\|U_N\|_{H^4}^2+\nu\|\nabla_LU_N\|_{H^4}^2
 \leq C(1+\|U_N\|_{H^4})\|U_N\|_{H^4}^2.
\end{equation*}
Consequently, for some $\tau_{0}=\tau_{0}(\|u_{\rm in}\|_{H^4})\in(0,1]$,
\begin{equation}
 \sup_N\left(\|U_N\|_{L^\infty(0,\tau_{0};H^4)}^2
       +\nu\|\nabla_LU_N\|_{L^2(0,\tau_{0};H^4)}^2\right)
 \leq C(\|u_{\rm in}\|_{H^4}).
 \label{eq:Kelvin-local-uniform}
\end{equation}

For $N\geq M$, the nonlinear difference splits into
\begin{align*}
 &\mathcal J_N\bigl((U_N-U_M)\cdot\nabla_LU_N
                   +U_M\cdot\nabla_L(U_N-U_M)\bigr)\\
 &\qquad +(\mathcal J_N-\mathcal J_M)(U_M\cdot\nabla_LU_M).
\end{align*}
Using $\mathcal J_N(U_N-U_M)=U_N-U_M$, transport cancellation,
and the $H^3$ product estimate, Gronwall gives
\begin{align}
 &\|U_N-U_M\|_{L^\infty(0,\tau_{0};H^3)}^2
 +\nu\|\nabla_L(U_N-U_M)\|_{L^2(0,\tau_{0};H^3)}^2\nonumber\\
 &\quad\leq C_{\nu,\tau_{0},u_{\rm in}}
 \Bigl(\|(\mathcal J_N-\mathcal J_M)u_{\rm in}\|_{H^3}^2
 +\|(\mathcal J_N-\mathcal J_M)(U_M\cdot\nabla_LU_M)\|_{L^2(0,\tau_{0};H^3)}^2\Bigr).
 \label{eq:Friedrichs-Cauchy}
\end{align}
The last norm is at most
$CM^{-1}\|U_M\|_{L^\infty H^4}\|U_M\|_{L^2H^5}$ and tends to zero.
Hence $U_N$ converges strongly in $C_tH^3\cap L_t^2H^4$, and
\begin{equation}
 U\in L^\infty(0,\tau_{0};H^4)\cap L^2(0,\tau_{0};H^5).
 \label{eq:Kelvin-limit-bounds}
\end{equation}
The product estimate implies convergence of the nonlinear term in
$L_t^2H^3$, and the bounded pressure multipliers give convergence
of the pressure gradients in the same space. This yields
\eqref{eq:Kelvin-local-system}--\eqref{eq:Kelvin-pressure-local} and
$\partial_tU\in L_t^2H^3$. The Hilbert triple
$H^5\hookrightarrow H^4\hookrightarrow H^3$ gives $U\in C_tH^4$.
The same difference estimate proves uniqueness and continuous dependence.

Restarting with $X=x-(t-t_{0})y$ gives a local lifespan depending only
on $\nu$ and $\|u(t_{0})\|_{H^4}$, proving \eqref{eq:H4-blowup-alternative}.
For the energy criterion, skew-adjointness of $y\partial_x$ and
$[\partial^\alpha,y\partial_x]=\alpha_y\partial_x\partial^{\alpha-e_y}$,
together with the Moser estimate, yield
\begin{equation}
 \frac{d}{dt}\|u(t)\|_{H^4}^2+\nu\|\nabla u(t)\|_{H^4}^2
 \leq C(1+\|\nabla u(t)\|_{L^\infty})\|u(t)\|_{H^4}^2.
 \label{eq:H4-continuation-revised}
\end{equation}
This energy inequality follows first for the regularized solutions with transverse
cutoffs and then by passage to the limit. The definitions and the
streamwise Poincar\'e inequality give, for $0\leq t\leq T<T_{\max}$,
\begin{equation*}
 \|\nabla u(t)\|_{L^\infty}
 \leq C\bigl(\|u^1_{0}(t)\|_{H^4}
             +\|u^\perp_{0}(t)\|_{H^4}+\|u_{\neq}(t)\|_{H^3}\bigr)
 \leq C(E_{1}(T)+E_{3}(T)+E_{5}(T)).
\end{equation*}
Under \eqref{eq:continuation-uniform-revised}, this is integrable up to
any finite $T_{\max}$. Gronwall in \eqref{eq:H4-continuation-revised}
contradicts \eqref{eq:H4-blowup-alternative}, proving continuation.

\label{lem:bootstrap-continuity-final}
		Let $u$ be an $H^4$ strong solution on a compact interval $[0,T_{0}]\subset[0,T_{\max})$, with
$u^\perp_0(0)\in\dot B^{-2}_{2,\infty}(\mathbb R^2)$.
Assume that the shear coordinates used in the nonzero-mode module are admissible on this interval, in the sense that $\inf_{[0,T_{0}]\times\mathbb R^2}V_y>0$, and construct the auxiliary variables as above. Then
		\begin{equation*}
			T\longmapsto E_{1}(T),\ E_{2}(T),\ E_{3}(T),\ E_{4}(T),\ E_{5}(T),\ E_{6}(T)
		\end{equation*}
		are finite, nondecreasing, and continuous on $[0,T_{0}]$. The correctors $q^{(2)},q^{(3)}$, the second good unknown $q^{(1)}$, and the complementary scalar $\Delta u^3_{\neq}-2\partial_xq^{(3)}$ are also strongly continuous at every Sobolev level used in their energy estimates.

The strong-solution regularity and compact-time Kelvin equivalence give
\begin{equation}
 u^1_{0},\ u^\perp_{0},\ u_{\neq}
 \in C([0,T_{0}];H^4)\cap L^2(0,T_{0};H^5).
 \label{eq:bootstrap-continuity-basic-variables}
\end{equation}
Since $V_y$ is bounded away from zero, Moser composition gives
\begin{equation}
 \kappa\in C_tH^3(\mathbb R^2),\qquad
 (\rho_1,\rho_2)\in C_tH^2(\mathbb R^2).
 \label{eq:bootstrap-continuity-coefficients}
\end{equation}
Thus $q,D_z^Vu_{\neq}\in C_tH^3$; the streak equation also gives
$\partial_tu^1_{0}\in C_tH^2$.

For the correctors, set
\begin{equation}
 \widetilde{q^{(i)}}(t,X,y,z)=q^{(i)}(t,X+ty,y,z),\qquad i=2,3.
 \label{eq:corrector-Kelvin-pullback}
\end{equation}
Their equations are
\begin{align}
 \partial_t\widetilde{q^{(2)}}-\nu\Delta_L\widetilde{q^{(2)}}
 +u^1_{0}\partial_X\widetilde{q^{(2)}}
 &=-\rho_1\bigl(V_y(\partial_y-t\partial_X)+V_z\partial_z\bigr)
       \widetilde{u^3_{\neq}},\nonumber\\
 \partial_t\widetilde{q^{(3)}}-\nu\Delta_L\widetilde{q^{(3)}}
 +u^1_{0}\partial_X\widetilde{q^{(3)}}
 &=-\bigl(V_y(\partial_y-t\partial_X)+V_z\partial_z\bigr)
       \widetilde{u^3_{\neq}},
 \label{eq:corrector-Kelvin-equations}
\end{align}
with zero initial data. By \eqref{eq:bootstrap-continuity-basic-variables}--\eqref{eq:bootstrap-continuity-coefficients},
the sources belong to $L_t^2H^2$ and $L_t^2H^3$, respectively.
Parabolic energy estimates and the equations therefore give
\begin{align*}
 \widetilde{q^{(2)}}&\in L_t^\infty H^2\cap L_t^2H^3,
 &\partial_t\widetilde{q^{(2)}}&\in L_t^2H^1,\\
 \widetilde{q^{(3)}}&\in L_t^\infty H^3\cap L_t^2H^4,
 &\partial_t\widetilde{q^{(3)}}&\in L_t^2H^2.
\end{align*}
The Hilbert-triple continuity theorem and the continuous inverse Kelvin
transform yield $q^{(2)}\in C_tH^2$ and $q^{(3)}\in C_tH^3$.
It follows that $q^{(1)}$ and $\Delta u^3_{\neq}-2\partial_xq^{(3)}$
belong to $C_tH^2$. The remaining auxiliary quantities are Sobolev
products or bounded elliptic multipliers of these fields.
Every ordinary energy component is consequently a running maximum
of a continuous norm or an integral of an $L^1$ function, and is continuous in $T$.

For the endpoint component, the Duhamel formula and \Cref{lem:div-B,lem:average-products} first give
\begin{equation*}
 \sup_{0\leq t\leq T_0}\|u^\perp_0(t)\|_{\dot B^{-2}_{2,\infty}}
 \leq C\|u^\perp_0(0)\|_{\dot B^{-2}_{2,\infty}}
 +C\int_0^{T_0}\bigl(\|u^\perp_0(s)\|_{L^2}^2
 +\|u^\perp_{\neq}(s)\|_{L^2}^2\bigr)\,ds<\infty.
\end{equation*}
The dyadic heat multiplier satisfies
\begin{equation*}
 \|\dot\Delta_j(\mathrm e^{\nu h\Delta_{\!\perp}}-I)f\|_{L^2}
 \leq C\min\{1,\nu h2^{2j}\}\|\dot\Delta_jf\|_{L^2}.
\end{equation*}
Since $2^{-2j}\min\{1,\nu h2^{2j}\}\leq\nu h$, this gives directly
\begin{equation}
 \|(\mathrm e^{\nu h\Delta_{\!\perp}}-I)f\|_{\dot B^{-2}_{2,\infty}}
 \leq C\nu h\|f\|_{L^2}\longrightarrow0
 \qquad(h\downarrow0).
 \label{eq:heat-strong-continuity-Bminus2}
\end{equation}
For $0\leq t_1<t_2\leq T_{0}$, Duhamel gives
\begin{align}
 u^\perp_{0}(t_2)-u^\perp_{0}(t_1)
 ={}&(\mathrm e^{\nu(t_2-t_1)\Delta_{\!\perp}}-I)u^\perp_{0}(t_1)\nonumber\\
 &-\int_{t_1}^{t_2}\mathrm e^{\nu(t_2-s)\Delta_{\!\perp}}\mathbb P_{\!\perp}\nabla_{\!\perp}\cdot
 \bigl(u^\perp_{0}\otimes u^\perp_{0}
       +(u^\perp_{\neq}\otimes u^\perp_{\neq})_{0}\bigr)(s)\,ds.
 \label{eq:R-Besov-continuity-Duhamel}
\end{align}
By \Cref{lem:div-B,lem:average-products} and \eqref{eq:heat-strong-continuity-Bminus2},
\begin{align}
 \|u^\perp_{0}(t_2)-u^\perp_{0}(t_1)\|_{\dot B^{-2}_{2,\infty}}
 \leq{}&C\nu(t_2-t_1)\|u^\perp_{0}(t_1)\|_{L^2}\nonumber\\*
 &+C\int_{t_1}^{t_2}(\|u^\perp_{0}(s)\|_{L^2}^2+\|u^\perp_{\neq}(s)\|_{L^2}^2)\,ds.
 \label{eq:R-Besov-continuity-bound}
\end{align}
The right-hand side tends to zero uniformly as $t_2-t_1\to0$.
Thus the Besov norm and its running maximum are continuous.
Monotonicity of all six energies follows from their definitions.

\label{lem:Besov-lower-semicontinuity-final}
		Let $f_n,f\in C([0,T];L^2(\mathbb R^2))$ and assume
		\begin{equation}
			f_n\longrightarrow f\qquad\hbox{in }C([0,T];L^2(\mathbb R^2)).
			\label{eq:Besov-lsc-strong-L2}
		\end{equation}
		Then, with values in $[0,\infty]$,
		\begin{equation}
			\sup_{0\leq t\leq T}\|f(t)\|_{\dot B^{-2}_{2,\infty}}
			\leq
			\liminf_{n\to\infty}\sup_{0\leq t\leq T}\|f_n(t)\|_{\dot B^{-2}_{2,\infty}}.
			\label{eq:Besov-lsc-terminal}
		\end{equation}
		In particular, a uniform $L_t^\infty\dot B^{-2}_{2,\infty}$ bound passes to the strong $C_tL^2$ limit.

\label{lem:H4-approx-stability-final}
		Let $u_n$ and $u$ be $H^4$ strong solutions on $[0,T]$ such that
		\begin{equation}
			u_n\longrightarrow u
			\quad\hbox{in}\quad
			C([0,T];H^3)\cap L^2(0,T;H^4),
			\label{eq:H4-approx-strong}
		\end{equation}
		and
		\begin{equation}
			\sup_n\left(
			\|u_n\|_{L^\infty(0,T;H^4)}
			+\|u_n\|_{L^2(0,T;H^5)}
			\right)<\infty.
			\label{eq:H4-approx-uniform}
		\end{equation}
		Assume that the associated shear maps are uniformly admissible on $[0,T]$. Construct the coefficients, good unknowns, parabolic correctors, and complementary scalar from $u_n$ and $u$ by the formulas in Section~\ref{sec:framework-notation} and Appendix~\ref{sec:second-good}. Then the auxiliary variables associated with $u_n$ converge to those associated with $u$ strongly at one derivative below their top energy level and weakly at the top level. In particular, every Sobolev part of
		\begin{equation*}
			E_{1}(T),\ E_{2}(T),\ E_{3}(T),\ E_{4}(T),\ E_{5}(T),\ E_{6}(T)
		\end{equation*}
		is lower semicontinuous under \eqref{eq:H4-approx-strong}--\eqref{eq:H4-approx-uniform}, and the endpoint component satisfies
		\begin{equation}
			\sup_{0\leq t\leq T}\|u^\perp_{0}(t)\|_{\dot B^{-2}_{2,\infty}}
			\leq
			\liminf_{n\to\infty}\sup_{0\leq t\leq T}\|(u_n^\perp)_{0}(t)\|_{\dot B^{-2}_{2,\infty}}.
			\label{eq:H4-approx-Besov-lsc}
		\end{equation}
